sp_widget.client_script:
/**
 * File Manager Widget (PRIVATE) - Client Script
 * AngularJS Controller + Link Function
 * Public files are handled by the separate "public_files" widget / page.
 */

api.controller = function ($scope, $http, $timeout, $location, $filter, $templateCache) {
    var c = this;

    /* >>> CHANGE THIS to the Page ID of your Public_file_manger page <<< */
    var PUBLIC_PAGE_ID = 'public_file_manger';

    /* ===================================================
       STATE
    =================================================== */
    c.view = 'home';   // home | allfiles | folders | files | shared | recycle | storage
    c.homeSubView = '';
    c.sharedView = 'withMe'; // withMe | byMe
    c.viewMode = 'list';   // list | grid
    c.pageSize = 10;
    c.currentPages = { allFiles: 1, rootFolders: 1, childFolders: 1, folderFiles: 1, sharedFolders: 1, sharedFiles: 1, sharedByMe: 1 };
    c.currentFolder = '';
    c.currentFolderName = '';
    c.searchText = '';
    c.loading = false;
    c.breadcrumb = [];

    /* This widget is private-only. These helpers are kept so the template keeps working. */
    c.isPublic = function () { return false; };
    c.canCreate = function () { return true; };

    c.filesCount = function () { return ((c.data && c.data.files) || []).length; };

    c.setViewMode = function (m) { c.viewMode = m; };

    /** Link to the public page (keeps the picker parameters) */
    c.publicPageUrl = function () {
        var url = '?id=' + PUBLIC_PAGE_ID;
        if (c.pickerMode) {
            url += '&picker=true&target_table=' + encodeURIComponent(c.targetTable) +
                   '&target_sys_id=' + encodeURIComponent(c.targetSysId);
        }
        return url;
    };

    c.sidebarStoragePct = function () {
        var total = (c.data && c.data.storage && c.data.storage.totalBytes) || 0;
        var max = 5 * 1073741824; // 5 GB
        return Math.min(100, Math.max(2, Math.round((total / max) * 100)));
    };

    c.folderSort = 'folder_name';   // folder_name | -folder_name | -sys_created_on
    c.fileSort = 'filename';
    c.fileTypeFilter = '';

    // Modals
    c.showFolderModal = false;
    c.showShareModal = false;
    c.showEditFileModal = false;
    c.showRenameFileModal = false;
    c.showUploadFolderPicker = false;
    c.showAddToFolderModal = false;
    c.showNicknameModal = false;
    c.pendingItems = [];
    c.previewFile = null;

    c.addToFolderTarget = null;
    c.addToFolderType = 'file';
    c.selectedAddFolder = '';
    c.copyBusy = false;

    c.targetUploadFolder = '';
    c.targetUploadFolderName = '';

    c.newFolderName = '';
    c.newFolderDescription = '';
    c.newFolderColor = 'orange';
    c.editFolderTarget = null;

    c.folderColors = [
        { id: 'orange', name: 'Orange', hex: '#f59e0b', bg: '#fffbeb', text: '#d97706' },
        { id: 'blue', name: 'Blue', hex: '#3b82f6', bg: '#eff6ff', text: '#2563eb' },
        { id: 'purple', name: 'Purple', hex: '#8b5cf6', bg: '#f5f3ff', text: '#7c3aed' },
        { id: 'green', name: 'Green', hex: '#10b981', bg: '#ecfdf5', text: '#059669' },
        { id: 'pink', name: 'Pink', hex: '#ec4899', bg: '#fdf2f8', text: '#db2777' }
    ];

    c.getFolderColor = function (folderId, file) {
        if (file && file.folder_color) return file.folder_color;
        if (!folderId) return 'orange';
        var f = _allFolders().filter(function (item) { return item.sys_id === folderId; })[0];
        return (f && f.color) ? f.color : 'orange';
    };

    c.renameFileTarget = null;
    c.renameFileName = '';

    c.shareRecipientType = 'user';
    c.selectedUsers = [];
    c.selectedGroups = [];
    c.shareExpirationDate = null;
    c.shareTarget = null;
    c.shareType = 'file';
    c.userSearchText = '';
    c.groupSearchText = '';

    c.editFileTarget = null;
    c.editFileDescription = '';
    c.editFileNickname = '';

    c.confirmModal = { show: false, title: '', message: '', confirmLabel: 'Confirm', danger: false, icon: 'fa-check', onConfirm: angular.noop };
    c.contextMenu = { show: false, x: 0, y: 0, item: null, type: '' };

    c.uploading = false;
    c.uploadProgress = 0;
    c.uploadIndex = 0;
    c.uploadTotal = 0;
    c.uploadCurrentName = '';

    c.allSelected = false;
    c.dragOver = false;
    c.message = '';
    c.error = '';
    c.undo = null;

    /* Reusable pager template (used with ng-include + onload="pgKey='...'") */
    $templateCache.put('fm-pager.html',
        '<div class="fm-pagination" ng-if="c.page(pgKey).total">' +
        '<span>Showing {{c.page(pgKey).start}}–{{c.page(pgKey).end}} of {{c.page(pgKey).total}}</span>' +
        '<div class="fm-pagination-controls">' +
        '<select ng-model="c.pageSize" ng-options="n for n in [10, 20, 50]" aria-label="Rows per page"></select>' +
        '<button type="button" title="First page" ng-click="c.goToPage(pgKey, 1)" ng-disabled="c.page(pgKey).page <= 1">&laquo;</button>' +
        '<button type="button" ng-click="c.previousPage(pgKey)" ng-disabled="c.page(pgKey).page <= 1">Previous</button>' +
        '<button type="button" class="fm-page-num" ng-repeat="n in c.pageNumbers(pgKey) track by $index" ' +
        'ng-class="{\'fm-page-active\': n === c.page(pgKey).page}" ng-disabled="n === \'…\'" ng-click="c.goToPage(pgKey, n)">{{n}}</button>' +
        '<button type="button" ng-click="c.nextPage(pgKey)" ng-disabled="c.page(pgKey).page >= c.page(pgKey).pages">Next</button>' +
        '<button type="button" title="Last page" ng-click="c.goToPage(pgKey, c.page(pgKey).pages)" ng-disabled="c.page(pgKey).page >= c.page(pgKey).pages">&raquo;</button>' +
        '</div></div>');

    /* ===================================================
       PICKER MODE (opened from the attachment dialog)
    =================================================== */
    var _qs = $location.search();

    c.pickerMode = _qs.picker === 'true';
    c.targetTable = _qs.target_table || '';
    c.targetSysId = _qs.target_sys_id || '';
    c.pickBusy = false;

    c.getSelectedFiles = function () {
        var seen = {};
        return ((c.data && c.data.files) || []).concat((c.data && c.data.sharedFiles) || []).filter(function (f) {
            if (!f._selected || seen[f.sys_id]) return false;
            seen[f.sys_id] = true;
            return true;
        });
    };

    c.attachFiles = function (ids) {
        if (c.pickBusy || !ids || !ids.length) return;

        if (!c.targetTable || !c.targetSysId) {
            c.error = 'Missing target record. Open this page from the attachment dialog.';
            return;
        }

        c.pickBusy = true;
        _clearAlerts();

        c.server.get({
            action: 'attach_to_record', file_ids: ids,
            target_table: c.targetTable, target_sys_id: c.targetSysId
        }).then(function (res) {
            c.pickBusy = false;
            var r = (res && res.data) ? res.data : res;

            if (r && r.attached_count > 0) {
                var msg = { type: 'FM_FILE_ATTACHED', count: r.attached_count };
                try { var ch = new BroadcastChannel('fm_attach_channel'); ch.postMessage(msg); ch.close(); } catch (e) { }
                try { if (window.opener) window.opener.postMessage(msg, window.location.origin); } catch (e) { }

                if (r.error) c.error = r.error;
                else window.close();
            } else {
                c.error = (r && r.error) || 'Could not attach the selected file(s).';
            }
        }, function () {
            c.pickBusy = false;
            c.error = 'Server request failed. Please try again.';
        });
    };

    c.attachSelected = function () {
        c.attachFiles(c.getSelectedFiles().map(function (f) { return f.sys_id; }));
    };

    /** Double-click: attach (picker mode) or preview (images) */
    c.onRowDblClick = function (file) {
        if (!file || !file.sys_id) return;
        if (c.pickerMode) { c.attachFiles([file.sys_id]); return; }
        if (c.isImage(file)) c.preview(file);
    };

    /** Picker mode: clicking a row toggles its selection */
    c.rowClick = function (file, $event) {
        c.closeContextMenu();
        if (!c.pickerMode || !file) return;
        var t = $event && $event.target;
        if (t && /^(INPUT|BUTTON|A)$/i.test(t.tagName)) return;
        file._selected = !file._selected;
        c.onFileSelect();
    };

    /* ===================================================
       NAVIGATION
    =================================================== */

    function _resetNav(view, subView) {
        c.view = view;
        c.homeSubView = subView || '';
        c.currentFolder = '';
        c.currentFolderName = '';
        c.searchText = '';
        c.breadcrumb = [];
        _clearAlerts();
        _clearSelection();
        c.closeContextMenu();
    }

    c.setHomeSubView = function (subView) {
        _resetNav('home', subView);
        if (subView === 'shared') c.sharedView = 'withMe';
        c.resetPagination();
    };
    c.goHome = function () { _resetNav('home', ''); c.resetPagination(); };
    c.setView = function (view) {
        _resetNav(view, '');
        if (view === 'shared') c.sharedView = 'withMe';
        c.resetPagination();
    };

    function _allFolders() {
        return ((c.data && c.data.folders) || []).concat((c.data && c.data.sharedFolders) || []);
    }
    function _allFiles() {
        return ((c.data && c.data.files) || []).concat((c.data && c.data.sharedFiles) || []);
    }

    /** Build [root, ...ancestors, folder] crumbs by walking parent_folder links */
    function _buildCrumbs(folder) {
        var map = {};
        _allFolders().forEach(function (f) { map[f.sys_id] = f; });

        var owned = ((c.data && c.data.folders) || []).some(function (f) { return f.sys_id === folder.sys_id; });
        var root = owned ? { id: '', name: 'Folders', view: 'folders' }
            : { id: '', name: 'Shared with Me', view: 'shared' };

        var chain = [], cur = folder, guard = 0;
        while (cur && guard++ < 25) {
            chain.unshift({ id: cur.sys_id, name: cur.folder_name });
            cur = cur.parent_folder ? map[cur.parent_folder] : null;
        }
        return [root].concat(chain);
    }

    c.openFolder = function (folder, rebuild) {
        if (!folder) return;

        if (c.view === 'files' && !rebuild && c.breadcrumb.length) {
            c.breadcrumb.push({ id: folder.sys_id, name: folder.folder_name });
        } else {
            c.breadcrumb = _buildCrumbs(folder);
        }

        c.currentFolder = folder.sys_id;
        c.currentFolderName = folder.folder_name;
        c.view = 'files';
        c.homeSubView = '';
        c.searchText = '';
        c.resetPagination();
        _clearAlerts();
        _clearSelection();
        c.closeContextMenu();
    };

    c.openFolderById = function (folderId) {
        if (!folderId) return;
        var folder = _allFolders().filter(function (f) { return f.sys_id === folderId; })[0];
        if (folder) c.openFolder(folder, true);
    };

    c.navigateBreadcrumb = function (index) {
        var crumb = c.breadcrumb[index];
        if (!crumb) return;

        if (!crumb.id) { c.setView(crumb.view || 'folders'); return; }

        c.breadcrumb = c.breadcrumb.slice(0, index + 1);
        c.currentFolder = crumb.id;
        c.currentFolderName = crumb.name;
        c.view = 'files';
        c.homeSubView = '';
        c.searchText = '';
        c.resetPagination();
        _clearSelection();
        c.closeContextMenu();
    };

    c.navigateBack = function () {
        if (c.breadcrumb.length > 2) c.navigateBreadcrumb(c.breadcrumb.length - 2);
        else c.navigateBreadcrumb(0);
    };

    c.backLabel = function () {
        if (c.breadcrumb.length > 2) return 'Back';
        return 'Back to ' + ((c.breadcrumb[0] && c.breadcrumb[0].name) || 'Folders');
    };

    /* ===================================================
       FOLDER & FILE QUERIES
    =================================================== */

    c.rootFolders = function () {
        return ((c.data && c.data.folders) || []).filter(function (f) { return !f.parent_folder; });
    };
    c.sharedRootFolders = function () {
        return ((c.data && c.data.sharedFolders) || []).filter(function (f) { return f.share_root; });
    };
    c.sharedRootFiles = function () {
        return ((c.data && c.data.sharedFiles) || []).filter(function (f) { return f.share_root; });
    };
    c.sharedCount = function () { return c.sharedRootFolders().length + c.sharedRootFiles().length; };
    c.recycleCount = function () {
        return (((c.data && c.data.recycleFiles) || []).length) + (((c.data && c.data.recycleFolders) || []).length);
    };

    c.editableFolders = function () {
        var owned = (c.data && c.data.folders) || [];
        var sharedEdit = ((c.data && c.data.sharedFolders) || []).filter(function (f) { return f.can_edit; });
        return owned.concat(sharedEdit);
    };

    c.ownedFolders = function () {
        return ((c.data && c.data.folders) || []).filter(function (f) { return f.permission === 'Owner'; });
    };

    c.foldersInCurrentFolder = function () {
        var seen = {};
        return _allFolders().filter(function (f) {
            if (!f || seen[f.sys_id]) return false;
            seen[f.sys_id] = true;
            return (f.parent_folder || '') === (c.currentFolder || '');
        });
    };

    c.filesInCurrentFolder = function () {
        var seen = {};
        return _allFiles().filter(function (f) {
            if (!f || seen[f.sys_id]) return false;
            seen[f.sys_id] = true;
            return (f.folder || '') === (c.currentFolder || '');
        });
    };

    c.currentFolderCanEdit = function () {
        if (!c.currentFolder) return false;
        var match = _allFolders().filter(function (f) { return f.sys_id === c.currentFolder; })[0];
        return !!(match && match.can_edit);
    };

    c.getFolderName = function (folderId, file) {
        if (file && file.folder_name) return file.folder_name;
        if (!folderId) return '';
        var f = _allFolders().filter(function (item) { return item.sys_id === folderId; })[0];
        return f ? f.folder_name : '';
    };

    c.allFilesFiltered = function () {
        var source = (c.data && c.data.files) || [];
        return source.filter(function (file) {
            if (c.searchText) {
                var hit = c.matchFile(file);
                if (!hit) return false;
            }
            if (!c.fileTypeFilter) return true;

            var ext = (file.file_extension || '').toLowerCase();
            switch (c.fileTypeFilter) {
                case 'image': return ['png', 'jpg', 'jpeg', 'gif', 'webp', 'bmp', 'svg'].indexOf(ext) !== -1;
                case 'document': return ['doc', 'docx', 'odt', 'rtf', 'txt', 'md', 'xls', 'xlsx', 'csv', 'ppt', 'pptx'].indexOf(ext) !== -1;
                case 'pdf': return ext === 'pdf';
                case 'archive': return ['zip', 'rar', '7z', 'tar', 'gz'].indexOf(ext) !== -1;
                default: return true;
            }
        });
    };

    c.searchFiles = function (file) {
        return c.matchFile(file);
    };

    c.searchFolders = function (folder) {
        if (!c.searchText) return true;
        return (folder.folder_name || '').toLowerCase().indexOf(c.searchText.toLowerCase()) !== -1;
    };

    /** Newest 5 files (server already returns owned files newest-first) */
    c.recentFiles = function () { return ((c.data && c.data.files) || []).slice(0, 5); };

    /* ---- file / folder counts shown on folder cards (cached per data load) ---- */
    var _cc = { ref: null, f: {}, d: {} };
    function _buildCounts() {
        if (_cc.ref === c.data) return;
        _cc = { ref: c.data, f: {}, d: {} };
        var seenF = {}, seenD = {};
        _allFiles().forEach(function (x) {
            if (!x.folder || seenF[x.sys_id]) return;
            seenF[x.sys_id] = 1;
            _cc.f[x.folder] = (_cc.f[x.folder] || 0) + 1;
        });
        _allFolders().forEach(function (x) {
            if (!x.parent_folder || seenD[x.sys_id]) return;
            seenD[x.sys_id] = 1;
            _cc.d[x.parent_folder] = (_cc.d[x.parent_folder] || 0) + 1;
        });
    }
    /** "1 file" / "3 files" */
    c.countLabel = function (n, word) { return n + ' ' + word + (n === 1 ? '' : 's'); };

    c.folderCounts = function (folder) {
        _buildCounts();
        return { files: _cc.f[folder.sys_id] || 0, folders: _cc.d[folder.sys_id] || 0 };
    };

    /** Find an item by type + id (used by the right-click handler) */
    c.findItem = function (type, id) {
        var d = c.data || {};
        var lists = {
            file: (d.files || []).concat(d.sharedFiles || []),
            folder: (d.folders || []).concat(d.sharedFolders || []),
            recycle_file: d.recycleFiles || [],
            recycle_folder: d.recycleFolders || []
        };
        return (lists[type] || []).filter(function (x) { return x.sys_id === id; })[0] || null;
    };

    /* ===================================================
       CLIENT-SIDE LISTS + PAGINATION
    =================================================== */
    function _sortFiles(list) { return $filter('orderBy')(list, c.fileSort); }
    function _sortFolders(list) { return $filter('orderBy')(list, c.folderSort); }

    var _lists = {
        allFiles: function () { return _sortFiles(c.allFilesFiltered()); },
        rootFolders: function () { return _sortFolders(c.rootFolders().filter(c.searchFolders)); },
        childFolders: function () { return _sortFolders(c.foldersInCurrentFolder().filter(c.searchFolders)); },
        folderFiles: function () { return _sortFiles(c.filesInCurrentFolder().filter(c.searchFiles)); },
        sharedFolders: function () { return _sortFolders(c.sharedRootFolders().filter(c.searchFolders)); },
        sharedFiles: function () { return _sortFiles(c.sharedRootFiles().filter(c.searchFiles)); },
        sharedByMe: function () {
            var q = (c.searchText || '').toLowerCase();
            return ((c.data && c.data.sharedByMe) || []).filter(function (s) {
                if (!q) return true;
                return (s.item_name || '').toLowerCase().indexOf(q) !== -1 ||
                    (s.shared_with || '').toLowerCase().indexOf(q) !== -1;
            });
        }
    };

    c.page = function (key) {
        var fn = _lists[key];
        var list = fn ? fn() : [];
        var pages = Math.max(1, Math.ceil(list.length / c.pageSize));
        var page = Math.min(Math.max(c.currentPages[key] || 1, 1), pages);
        var start = (page - 1) * c.pageSize;
        return {
            items: list.slice(start, start + c.pageSize),
            page: page, pages: pages, total: list.length,
            start: list.length ? start + 1 : 0,
            end: Math.min(page * c.pageSize, list.length)
        };
    };
    c.goToPage = function (key, n) {
        if (typeof n !== 'number') return;
        c.currentPages[key] = Math.min(Math.max(1, n), c.page(key).pages);
    };
    /** Page buttons: 1 … 4 5 [6] 7 8 … 20 */
    c.pageNumbers = function (key) {
        var p = c.page(key), out = [], i;
        if (p.pages <= 7) { for (i = 1; i <= p.pages; i++) out.push(i); return out; }
        out.push(1);
        var from = Math.max(2, p.page - 1), to = Math.min(p.pages - 1, p.page + 1);
        if (from > 2) out.push('…');
        for (i = from; i <= to; i++) out.push(i);
        if (to < p.pages - 1) out.push('…');
        out.push(p.pages);
        return out;
    };
    c.previousPage = function (key) { c.currentPages[key] = Math.max(1, c.page(key).page - 1); };
    c.nextPage = function (key) { var p = c.page(key); c.currentPages[key] = Math.min(p.pages, p.page + 1); };
    c.resetPagination = function () {
        Object.keys(c.currentPages).forEach(function (key) { c.currentPages[key] = 1; });
    };
    c.setSharedView = function (view) {
        c.sharedView = view === 'byMe' ? 'byMe' : 'withMe';
        c.resetPagination();
        _clearSelection();
    };

    $scope.$watch(function () {
        return c.searchText + '|' + c.fileTypeFilter + '|' + c.pageSize + '|' + c.fileSort + '|' + c.folderSort;
    }, function (n, o) { if (n !== o) c.resetPagination(); });

    /* ===================================================
       SORTING
    =================================================== */
    c.toggleSort = function (field) {
        if (c.fileSort === field) c.fileSort = '-' + field;
        else if (c.fileSort === '-' + field) c.fileSort = field;
        else c.fileSort = field;
    };
    c.getSortIcon = function (field) {
        if (c.fileSort === field) return 'fa-sort-asc';
        if (c.fileSort === '-' + field) return 'fa-sort-desc';
        return 'fa-sort';
    };

    /* ===================================================
       SERVER ACTIONS & REFRESH
    =================================================== */

    /** c.data is replaced ONLY when the server says it fully loaded (data.loaded). */
    c.runAction = function (action, values) {
        values = values || {};
        values.action = action;
        _clearAlerts();

        return c.server.get(values).then(function (res) {
            var r = (res && res.data) ? res.data : res;
            if (r) {
                if (r.loaded) c.data = r;
                if (r.error) c.error = r.error;
                else if (r.success && !values.skip_load) c.message = r.success;
            }
            return r || {};
        }, function () {
            c.error = 'Server request failed. Please try again.';
            return { error: c.error };
        });
    };

    c.refresh = function (keepAlerts) {
        c.loading = true;
        if (keepAlerts !== true) _clearAlerts();

        return c.server.get({ action: 'refresh' }).then(function (res) {
            c.loading = false;
            var r = (res && res.data) ? res.data : res;
            if (r && r.loaded) c.data = r;
            return c.data;
        }, function () {
            c.loading = false;
            c.error = 'Unable to refresh. Please try again.';
            return c.data;
        });
    };

    /* Auto-dismiss success messages (longer when there is an Undo button) */
    var _msgTimer;
    $scope.$watch(function () { return c.message; }, function (v) {
        if (_msgTimer) $timeout.cancel(_msgTimer);
        if (v) _msgTimer = $timeout(function () { c.message = ''; c.undo = null; }, c.undo ? 8000 : 4000);
    });

    c.setUndo = function (fn) { c.undo = { fn: fn }; };
    c.runUndo = function () {
        var fn = c.undo && c.undo.fn;
        c.undo = null;
        if (fn) fn();
    };

    /* ===================================================
       UPLOAD
    =================================================== */

    c.openUploadFolderPicker = function () {
        var available = c.editableFolders();
        if (c.currentFolder && c.currentFolderCanEdit()) {
            c.targetUploadFolder = c.currentFolder;
            c.targetUploadFolderName = c.currentFolderName;
        } else if (available.length > 0) {
            c.targetUploadFolder = available[0].sys_id;
            c.targetUploadFolderName = available[0].folder_name;
        } else {
            c.targetUploadFolder = '';
            c.targetUploadFolderName = '';
        }
        c.showUploadFolderPicker = true;
    };

    /* The three entry points below receive plain arrays of File objects
       (the link function reads the <input> and passes the files in). */
    c.onPickerFilesSelected = function (files) {
        files = Array.prototype.slice.call(files || []);
        if (!files.length) return;
        var folderId = c.targetUploadFolder;
        c.showUploadFolderPicker = false;
        _uploadFilesToFolder(files, folderId);
    };

    c.onDirectFilesSelected = function (files) {
        files = Array.prototype.slice.call(files || []);
        if (!files.length) return;
        _uploadFilesToFolder(files, c.currentFolder);
    };

    /** Used by drag & drop onto a folder card */
    c.uploadToFolder = function (files, folderId) {
        files = Array.prototype.slice.call(files || []);
        if (!files.length) return;
        _uploadFilesToFolder(files, folderId);
    };

    /* ---- XML uploads: ask for an optional nickname before uploading ---- */
    function _isXml(file) { return /\.xml$/i.test((file && file.name) || ''); }

    c.stageUpload = function (items) {
        if (!items || !items.length) return;
        if (c.uploading) { c.error = 'An upload is already in progress. Please wait.'; return; }
        var hasXml = items.some(function (it) { return _isXml(it.file); });
        if (!hasXml) { _uploadItems(items); return; }
        items.forEach(function (it) { it.isXml = _isXml(it.file); it.nickname = ''; });
        c.pendingItems = items;
        c.showNicknameModal = true;
        _clearAlerts();
    };
    c.pendingOtherCount = function () {
        return (c.pendingItems || []).filter(function (it) { return !it.isXml; }).length;
    };
    c.confirmNicknameUpload = function () {
        var items = c.pendingItems || [];
        c.pendingItems = [];
        c.showNicknameModal = false;
        items.forEach(function (it) {
            it.nickname = it.isXml ? String(it.nickname || '').replace(/[\[\]]/g, '').trim().substring(0, 50) : '';
        });
        _uploadItems(items);
    };
    c.cancelNicknameUpload = function () { c.pendingItems = []; c.showNicknameModal = false; };

    /* search matches file name OR nickname */
    c.matchFile = function (file) {
        var q = (c.searchText || '').toLowerCase();
        if (!q) return true;
        return (file.filename || '').toLowerCase().indexOf(q) !== -1 ||
               (file.nickname || '').toLowerCase().indexOf(q) !== -1;
    };

    function _uploadFilesToFolder(fileList, folderId) {
        var files = Array.prototype.slice.call(fileList || []);
        if (!files.length) return;
        if (!folderId) { c.error = 'Please select a destination folder before uploading.'; return; }
        c.stageUpload(files.map(function (f) { return { file: f, folderId: folderId }; }));
    }

    /** items: [{ file: File, folderId: sys_id }] */
    function _uploadItems(items) {
        if (!items.length) return;
        if (c.uploading) { c.error = 'An upload is already in progress. Please wait.'; return; }

        var total = items.length, index = 0, failed = [];

        c.uploading = true;
        c.uploadProgress = 0;
        c.uploadIndex = 0;
        c.uploadTotal = total;
        c.uploadCurrentName = '';
        _clearAlerts();

        function finish() {
            c.uploading = false;
            c.refresh(true).then(function () {
                if (failed.length) {
                    c.error = 'Failed to upload: ' + failed.join(', ');
                } else {
                    c.message = total === 1
                        ? '"' + items[0].file.name + '" uploaded successfully.'
                        : total + ' files uploaded successfully.';
                }
            });
        }

        function next() {
            if (index >= total) { finish(); return; }

            var item = items[index++];
            var file = item.file;
            var ext = file.name.indexOf('.') !== -1 ? file.name.split('.').pop().toLowerCase() : '';

            c.uploadIndex = index;
            c.uploadCurrentName = file.name;
            c.uploadProgress = Math.round(((index - 1) / total) * 100);

            c.runAction('create_file', {
                filename: file.name, extension: ext,
                content_type: file.type || 'application/octet-stream',
                file_size: file.size, folder: item.folderId, nickname: item.nickname || '', skip_load: '1'
            }).then(function (result) {
                if (result.error || !result.file_sys_id) {
                    failed.push(file.name);
                    next();
                    return;
                }

                var uploadUrl =
                    '/api/now/attachment/file' +
                    '?table_name=x_1830514_fm_file' +
                    '&table_sys_id=' + encodeURIComponent(result.file_sys_id) +
                    '&file_name=' + encodeURIComponent(file.name);

                var token = window.g_ck || (c.data && c.data.g_ck) || '';
                var headers = { 'Content-Type': file.type || 'application/octet-stream', 'Accept': 'application/json' };
                if (token) headers['X-UserToken'] = token;

                $http.post(uploadUrl, file, { transformRequest: angular.identity, headers: headers }).then(function () {
                    c.uploadProgress = Math.round((index / total) * 100);
                    next();
                }, function () {
                    failed.push(file.name);
                    // remove the orphan record that has no attachment
                    c.runAction('discard_file', { sys_id: result.file_sys_id, skip_load: '1' }).then(function () { next(); });
                });
            });
        }
        next();
    }

    /* ---------- Folder upload (keeps the sub-folder structure) ---------- */

    c.openFolderUploadPicker = function () { c.triggerFolderUpload(); };

    c.triggerFolderUpload = function () {
        var input = document.getElementById('fmFolderUpload');
        if (input) { input.value = ''; input.click(); }
        else c.error = 'Folder upload input was not found.';
    };

    c.onFolderUploadSelected = function (files) {
        files = Array.prototype.slice.call(files || []);
        if (!files.length) return;
        if (c.currentFolder && !c.currentFolderCanEdit()) {
            c.error = 'You do not have permission to upload into this folder.';
            return;
        }
        _uploadFolderTree(files, c.currentFolder || '');
    };

    function _uploadFolderTree(files, baseParent) {
        if (c.uploading) { c.error = 'An upload is already in progress. Please wait.'; return; }

        var dirs = {};
        files.forEach(function (f) {
            var parts = (f.webkitRelativePath || f.name).split('/');
            parts.pop();
            var acc = '';
            parts.forEach(function (p) { acc = acc ? acc + '/' + p : p; dirs[acc] = true; });
        });

        var paths = Object.keys(dirs).sort(function (a, b) {
            var d = a.split('/').length - b.split('/').length;
            return d !== 0 ? d : (a < b ? -1 : 1);
        });

        if (!paths.length) { c.error = 'Unable to identify the selected folder.'; return; }

        var idMap = {}, i = 0;

        c.uploading = true;
        c.uploadTotal = files.length;
        c.uploadIndex = 0;
        c.uploadProgress = 0;
        c.uploadCurrentName = 'Creating folders...';
        _clearAlerts();

        function nextDir() {
            if (i >= paths.length) {
                c.uploading = false;
                var items = files.map(function (f) {
                    var parts = (f.webkitRelativePath || f.name).split('/');
                    parts.pop();
                    return { file: f, folderId: idMap[parts.join('/')] };
                }).filter(function (it) { return !!it.folderId; });
                c.stageUpload(items);
                return;
            }

            var path = paths[i++];
            var parts = path.split('/');
            var name = parts.pop();
            var parent = parts.length ? idMap[parts.join('/')] : baseParent;

            c.runAction('create_folder', {
                folder_name: name, description: 'Uploaded folder',
                parent_folder: parent || '', reuse_existing: '1', skip_load: '1'
            }).then(function (r) {
                if (r.error || !r.folder_sys_id) {
                    c.uploading = false;
                    c.error = r.error || ('Unable to create folder "' + name + '".');
                    return;
                }
                idMap[path] = r.folder_sys_id;
                nextDir();
            });
        }
        nextDir();
    }

    /* ===================================================
       CREATE & RENAME FOLDER
    =================================================== */

    c.openFolderModal = function () {
        c.newFolderName = '';
        c.newFolderDescription = '';
        c.newFolderColor = 'orange'; // Default is orange
        c.editFolderTarget = null;
        _clearAlerts();
        c.showFolderModal = true;
        $timeout(function () { var el = document.getElementById('fmFolderNameInput'); if (el) el.focus(); }, 60);
    };

    c.openRenameFolder = function (folder) {
        c.newFolderName = folder.folder_name;
        c.newFolderDescription = '';
        c.newFolderColor = folder.color || 'orange';
        c.editFolderTarget = folder;
        _clearAlerts();
        c.showFolderModal = true;
        $timeout(function () { var el = document.getElementById('fmFolderNameInput'); if (el) { el.focus(); el.select(); } }, 60);
    };

    c.closeFolderModal = function () {
        c.showFolderModal = false; c.editFolderTarget = null;
        c.newFolderName = ''; c.newFolderDescription = '';
        c.newFolderColor = 'orange';
    };

    c.onFolderNameKey = function ($event) {
        if ($event.keyCode === 13) {
            if (c.editFolderTarget) c.renameFolder(); else c.createFolder();
        }
    };

    c.createFolder = function () {
        var name = (c.newFolderName || '').trim();
        if (!name) { c.error = 'Please enter a folder name.'; return; }

        c.runAction('create_folder', {
            folder_name: name,
            description: c.newFolderDescription || '',
            parent_folder: c.currentFolder || '',
            color: c.newFolderColor || 'orange'
        }).then(function (result) {
            if (result.error) return;      // stay in the modal and show the error
            c.closeFolderModal();
        });
    };

    c.renameFolder = function () {
        var name = (c.newFolderName || '').trim();
        if (!name) { c.error = 'Please enter a folder name.'; return; }

        var target = c.editFolderTarget;
        c.runAction('rename_folder', {
            sys_id: target.sys_id,
            folder_name: name,
            color: c.newFolderColor || 'orange'
        }).then(function (result) {
            if (result.error) return;
            if (c.currentFolder === target.sys_id) c.currentFolderName = name;
            c.breadcrumb.forEach(function (b) { if (b.id === target.sys_id) b.name = name; });
            c.closeFolderModal();
        });
    };

    /* ===================================================
       RENAME FILE + EDIT DESCRIPTION
    =================================================== */

    c.openRenameFile = function (file) {
        c.renameFileTarget = file;
        c.renameFileName = file.filename;
        _clearAlerts();
        c.showRenameFileModal = true;
    };

    c.saveRenameFile = function () {
        var name = (c.renameFileName || '').trim();
        if (!name) { c.error = 'Please enter a file name.'; return; }
        c.runAction('rename_file', { sys_id: c.renameFileTarget.sys_id, filename: name }).then(function (r) {
            if (!r.error) { c.showRenameFileModal = false; c.renameFileTarget = null; }
        });
    };

    c.openEditFile = function (file) {
        c.editFileTarget = file;
        c.editFileDescription = file.description || '';
        c.editFileNickname = file.nickname || '';
        _clearAlerts();
        c.showEditFileModal = true;
    };

    /** save edited description */
    c.saveEditFile = function () {
        if (!c.editFileTarget) return;
        c.runAction('update_file', {
            sys_id: c.editFileTarget.sys_id, description: c.editFileDescription || '', nickname: c.editFileNickname || ''
        }).then(function (r) {
            if (!r.error) { c.showEditFileModal = false; c.editFileTarget = null; }
        });
    };

    /* ===================================================
       ADD SHARED FILE / FOLDER TO MY FOLDER (copy)
    =================================================== */

    c.openAddToFolder = function (item, type) {
        if (!item) return;
        c.addToFolderTarget = item;
        // Files also carry a folder_name, so the type must come from the caller
        c.addToFolderType = type || (item.filename ? 'file' : 'folder');
        c.selectedAddFolder = '';
        c.showAddToFolderModal = true;
        c.closeContextMenu();
        _clearAlerts();
    };

    c.closeAddToFolder = function () {
        c.showAddToFolderModal = false;
        c.addToFolderTarget = null;
        c.selectedAddFolder = '';
        c.copyBusy = false;
    };

    c.addSharedFileToFolder = function () {
        var item = c.addToFolderTarget;
        if (!item || !c.selectedAddFolder) { c.error = 'Please select a destination folder.'; return; }
        if (c.copyBusy) return;

        c.copyBusy = true;
        c.runAction('add_shared_file_to_folder', {
            sys_id: item.sys_id, folder_id: c.selectedAddFolder, item_type: c.addToFolderType
        }).then(function (r) {
            c.copyBusy = false;
            if (r.error) return;           // keep the modal open and show the error
            c.closeAddToFolder();          // server already reloaded the data
        });
    };

    /* ===================================================
       SHARE
    =================================================== */

    c.openShare = function (item, type) {
        c.shareTarget = item;
        c.shareType = type;
        c.shareRecipientType = 'user';
        c.selectedUsers = [];
        c.selectedGroups = [];
        c.shareExpirationDate = null;
        c.userSearchText = '';
        c.userSearchError = '';
        c.groupSearchText = '';
        c.groupSearchError = '';
        _clearAlerts();
        if (c.data) { c.data.users = []; c.data.groups = []; }
        c.showShareModal = true;
    };

    c.setShareRecipientType = function (type) {
        c.shareRecipientType = type;
        c.selectedUsers = []; c.selectedGroups = [];
        c.userSearchText = ''; c.groupSearchText = '';
        c.userSearchError = ''; c.groupSearchError = '';
        if (c.data) { c.data.users = []; c.data.groups = []; }
    };

    c.addUser = function (user) {
        if (!c.isUserSelected(user.sys_id)) c.selectedUsers.push(user);
        c.userSearchText = '';
        c.data.users = [];
    };
    c.removeUser = function (index) { c.selectedUsers.splice(index, 1); };
    c.isUserSelected = function (id) { return c.selectedUsers.some(function (u) { return u.sys_id === id; }); };

    c.addGroup = function (group) {
        if (!c.isGroupSelected(group.sys_id)) c.selectedGroups.push(group);
        c.groupSearchText = '';
        c.data.groups = [];
    };
    c.removeGroup = function (index) { c.selectedGroups.splice(index, 1); };
    c.isGroupSelected = function (id) { return c.selectedGroups.some(function (g) { return g.sys_id === id; }); };

    c.searchUsers = function () {
        if (c.userSearchTimer) $timeout.cancel(c.userSearchTimer);

        var term = (c.userSearchText || '').trim();
        c.userSearchError = '';
        if (c.data) c.data.users = [];
        if (term.length < 2) { c.userSearchLoading = false; return; }

        c.userSearchTimer = $timeout(function () {
            c.userSearchLoading = true;
            c.server.get({ action: 'search_users', search_term: term }).then(function (res) {
                if (term !== (c.userSearchText || '').trim()) return;
                var ret = (res && res.data) ? res.data : res;
                c.data.users = (ret && ret.users) || [];
                c.userSearchLoading = false;
            }, function () {
                c.userSearchLoading = false;
                c.userSearchError = 'Unable to search users.';
            });
        }, 300);
    };

    c.searchGroups = function () {
        if (c.groupSearchTimer) $timeout.cancel(c.groupSearchTimer);

        var term = (c.groupSearchText || '').trim();
        c.groupSearchError = '';
        if (c.data) c.data.groups = [];
        if (term.length < 2) { c.groupSearchLoading = false; return; }

        c.groupSearchTimer = $timeout(function () {
            c.groupSearchLoading = true;
            c.server.get({ action: 'search_groups', search_term: term }).then(function (res) {
                if (term !== (c.groupSearchText || '').trim()) return;
                var ret = (res && res.data) ? res.data : res;
                c.data.groups = (ret && ret.groups) || [];
                c.groupSearchLoading = false;
            }, function () {
                c.groupSearchLoading = false;
                c.groupSearchError = 'Unable to search groups.';
            });
        }, 300);
    };

    c.shareItem = function () {
        if (!c.shareTarget) { c.error = 'No item selected to share.'; return; }

        if (c.shareRecipientType === 'user' && c.selectedUsers.length === 0) { c.error = 'Please select at least one user to share with.'; return; }
        if (c.shareRecipientType === 'group' && c.selectedGroups.length === 0) { c.error = 'Please select at least one group to share with.'; return; }

        var expiry = '';
        if (c.shareExpirationDate) {
            var d = new Date(c.shareExpirationDate);
            if (isNaN(d.getTime())) { c.error = 'Invalid expiration date.'; return; }
            if (d.getTime() <= Date.now()) { c.error = 'Expiration date must be in the future.'; return; }
            expiry = d.toISOString();
        }

        c.runAction('share', {
            sys_id: c.shareTarget.sys_id, type: c.shareType, recipient_type: c.shareRecipientType,
            user_ids: c.selectedUsers.map(function (u) { return u.sys_id; }).join(','),
            group_ids: c.selectedGroups.map(function (g) { return g.sys_id; }).join(','),
            expiration_date: expiry
        }).then(function (result) {
            if (result.error) return;
            c.showShareModal = false;
            c.shareTarget = null;
        });
    };

    c.confirmRevoke = function (share) {
        _confirm({
            title: 'Revoke Access',
            message: 'Stop sharing "' + share.item_name + '" with ' + (share.shared_with || 'the recipients') + '?',
            confirmLabel: 'Revoke', icon: 'fa-ban',
            onConfirm: function () { c.runAction('revoke_share', { sys_id: share.sys_id }); }
        });
    };

    /* ===================================================
       CONFIRMATION & DELETION
    =================================================== */

    function _confirm(opts) {
        c.confirmModal = {
            show: true, title: opts.title || 'Are you sure?', message: opts.message || '',
            confirmLabel: opts.confirmLabel || 'Confirm', danger: opts.danger !== false,
            icon: opts.icon || 'fa-check', onConfirm: opts.onConfirm || angular.noop
        };
    }

    c.runConfirm = function () {
        var fn = c.confirmModal.onConfirm;
        c.confirmModal.show = false;
        fn();
    };

    c.confirmDeleteFile = function (file) {
        _confirm({
            title: 'Move to Recycle Bin', message: 'Move "' + file.filename + '" to the Recycle Bin?',
            confirmLabel: 'Move to Bin', icon: 'fa-trash',
            onConfirm: function () { c.deleteFile(file); }
        });
    };

    c.confirmDeleteFolder = function (folder) {
        _confirm({
            title: 'Move Folder to Recycle Bin',
            message: 'Move folder "' + folder.folder_name + '" to the Recycle Bin? Note: all subfolders and files inside must be removed or moved first.',
            confirmLabel: 'Move to Bin', icon: 'fa-trash',
            onConfirm: function () { c.deleteFolder(folder); }
        });
    };

    c.confirmPermanentDeleteFile = function (file) {
        _confirm({
            title: 'Delete File Permanently', message: 'Permanently delete "' + file.filename + '"? This action CANNOT be undone.',
            confirmLabel: 'Delete Permanently', icon: 'fa-times', danger: true,
            onConfirm: function () { c.deleteFilePermanent(file); }
        });
    };

    c.confirmPermanentDeleteFolder = function (folder) {
        _confirm({
            title: 'Delete Folder Permanently', message: 'Permanently delete folder "' + folder.folder_name + '"? This action CANNOT be undone.',
            confirmLabel: 'Delete Permanently', icon: 'fa-times', danger: true,
            onConfirm: function () { c.deleteFolderPermanent(folder); }
        });
    };

    c.canDeleteSelected = function () {
        return c.getSelectedFiles().some(function (f) { return f.permission === 'Owner'; });
    };

    c.confirmDeleteSelected = function () {
        var owned = c.getSelectedFiles().filter(function (f) { return f.permission === 'Owner'; });
        if (!owned.length) return;
        _confirm({
            title: 'Delete Selected Files',
            message: 'Move ' + owned.length + ' selected file(s) to the Recycle Bin? (Only files you own are deleted.)',
            confirmLabel: 'Move to Bin', icon: 'fa-trash',
            onConfirm: function () { _deleteBatch(owned); }
        });
    };

    c.confirmEmptyBin = function () {
        _confirm({
            title: 'Empty Recycle Bin',
            message: 'Permanently delete all files and folders in the Recycle Bin? This action CANNOT be undone.',
            confirmLabel: 'Empty Bin', icon: 'fa-trash', danger: true,
            onConfirm: function () { c.emptyBin(); }
        });
    };

    function _deleteBatch(files) {
        if (!files.length) { c.error = 'Only files you own can be moved to the Recycle Bin.'; return; }

        var idx = 0, done = 0, errors = [], doneIds = [];
        _clearAlerts();

        function next() {
            if (idx >= files.length) {
                c.refresh(true).then(function () {
                    if (errors.length) c.error = 'Could not delete: ' + errors.join(', ');
                    else {
                        c.message = done + ' file(s) moved to the Recycle Bin.';
                        c.setUndo(function () { _restoreBatch(doneIds); });
                    }
                });
                return;
            }
            var f = files[idx++];
            c.runAction('delete_file', { sys_id: f.sys_id, skip_load: '1' }).then(function (r) {
                if (r.error) errors.push(f.filename); else { done++; doneIds.push(f.sys_id); }
                next();
            });
        }
        next();
    }

    function _restoreBatch(ids) {
        var i = 0, ok = 0;
        function next() {
            if (i >= ids.length) {
                c.refresh(true).then(function () { c.message = ok + ' file(s) restored.'; });
                return;
            }
            c.runAction('restore_file', { sys_id: ids[i++], skip_load: '1' }).then(function (r) { if (!r.error) ok++; next(); });
        }
        next();
    }

    /* ===================================================
       CRUD ACTIONS (server reloads all data on success)
    =================================================== */

    c.deleteFile = function (file) {
        return c.runAction('delete_file', { sys_id: file.sys_id }).then(function (r) {
            if (!r.error) c.setUndo(function () { c.restoreFile({ sys_id: file.sys_id }); });
            return r;
        });
    };
    c.deleteFolder = function (folder) {
        return c.runAction('delete_folder', { sys_id: folder.sys_id }).then(function (r) {
            if (!r.error) c.setUndo(function () { c.restoreFolder({ sys_id: folder.sys_id }); });
            return r;
        });
    };
    c.restoreFile = function (file) { return c.runAction('restore_file', { sys_id: file.sys_id }); };
    c.restoreFolder = function (folder) { return c.runAction('restore_folder', { sys_id: folder.sys_id }); };
    c.deleteFilePermanent = function (file) { return c.runAction('delete_file_permanent', { sys_id: file.sys_id }); };
    c.deleteFolderPermanent = function (folder) { return c.runAction('delete_folder_permanent', { sys_id: folder.sys_id }); };
    c.emptyBin = function () { return c.runAction('empty_bin'); };

    /* ===================================================
       DOWNLOAD & PREVIEW
    =================================================== */

    c.downloadFile = function (file) {
        if (!file || !file.attachment_id) { c.error = 'Attachment not found.'; return; }
        window.open('/sys_attachment.do?sys_id=' + encodeURIComponent(file.attachment_id), '_blank');
    };

    c.downloadSelected = function () {
        c.getSelectedFiles().forEach(function (f, i) {
            $timeout(function () { c.downloadFile(f); }, i * 350);
        });
    };

    c.isImage = function (file) {
        if (!file) return false;
        var ext = (file.file_extension || '').toLowerCase();
        var type = (file.content_type || '').toLowerCase();
        return type.indexOf('image/') === 0 || ['png', 'jpg', 'jpeg', 'gif', 'webp', 'bmp', 'svg'].indexOf(ext) !== -1;
    };

    c.preview = function (file) {
        if (!file || !file.attachment_id) { c.error = 'Attachment not found.'; return; }
        c.previewFile = file;
    };
    c.closePreview = function () { c.previewFile = null; };

    /** Images available for ← / → navigation inside the preview */
    c.previewImages = function () {
        if (!c.previewFile) return [];
        var list = c.visibleFiles().filter(c.isImage);
        var found = list.some(function (f) { return f.sys_id === c.previewFile.sys_id; });
        return found ? list : [c.previewFile];
    };
    c.previewStep = function (dir) {
        var list = c.previewImages();
        if (list.length < 2) return;
        var idx = 0;
        for (var i = 0; i < list.length; i++) if (list[i].sys_id === c.previewFile.sys_id) idx = i;
        c.previewFile = list[(idx + dir + list.length) % list.length];
    };

    /* ===================================================
       FILE TYPE ICONS
    =================================================== */

    var _iconMap = {
        png: 'fa fa-file-image-o', jpg: 'fa fa-file-image-o', jpeg: 'fa fa-file-image-o',
        gif: 'fa fa-file-image-o', webp: 'fa fa-file-image-o', bmp: 'fa fa-file-image-o', svg: 'fa fa-file-image-o',
        pdf: 'fa fa-file-pdf-o',
        doc: 'fa fa-file-word-o', docx: 'fa fa-file-word-o', odt: 'fa fa-file-word-o',
        xls: 'fa fa-file-excel-o', xlsx: 'fa fa-file-excel-o', csv: 'fa fa-file-excel-o',
        ppt: 'fa fa-file-powerpoint-o', pptx: 'fa fa-file-powerpoint-o',
        zip: 'fa fa-file-zip-o', rar: 'fa fa-file-zip-o', '7z': 'fa fa-file-zip-o', tar: 'fa fa-file-zip-o', gz: 'fa fa-file-zip-o',
        mp3: 'fa fa-file-audio-o', wav: 'fa fa-file-audio-o',
        mp4: 'fa fa-file-video-o', avi: 'fa fa-file-video-o', mov: 'fa fa-file-video-o',
        js: 'fa fa-file-code-o', html: 'fa fa-file-code-o', css: 'fa fa-file-code-o', json: 'fa fa-file-code-o', py: 'fa fa-file-code-o',
        txt: 'fa fa-file-text-o', md: 'fa fa-file-text-o'
    };
    var _colorMap = {
        'fa fa-file-image-o': 'fm-icon-image', 'fa fa-file-pdf-o': 'fm-icon-pdf', 'fa fa-file-word-o': 'fm-icon-word',
        'fa fa-file-excel-o': 'fm-icon-excel', 'fa fa-file-powerpoint-o': 'fm-icon-ppt', 'fa fa-file-zip-o': 'fm-icon-zip',
        'fa fa-file-audio-o': 'fm-icon-audio', 'fa fa-file-video-o': 'fm-icon-video', 'fa fa-file-code-o': 'fm-icon-code',
        'fa fa-file-text-o': 'fm-icon-text'
    };

    c.getFileIcon = function (file) {
        if (!file) return 'fa fa-file-o';
        return _iconMap[(file.file_extension || '').toLowerCase()] || 'fa fa-file-o';
    };
    c.getFileIconColor = function (file) { return _colorMap[c.getFileIcon(file)] || 'fm-icon-default'; };

    /* ===================================================
       SELECTION HELPERS
    =================================================== */

    /** Files currently listed on screen (full filtered list of the active view) */
    c.visibleFiles = function () {
        var v = c.view === 'home' ? c.homeSubView : c.view;
        if (v === 'allfiles') return c.allFilesFiltered();
        if (v === 'files') return c.filesInCurrentFolder().filter(c.searchFiles);
        if (v === 'shared' && c.sharedView === 'withMe') return c.sharedRootFiles().filter(c.searchFiles);
        return [];
    };

    c.selectedCount = function () {
        return c.visibleFiles().filter(function (f) { return f._selected; }).length;
    };

    c.toggleSelectAll = function () {
        c.visibleFiles().forEach(function (f) { f._selected = c.allSelected; });
    };
    c.selectAllVisible = function () {
        c.allSelected = true;
        c.toggleSelectAll();
    };

    c.onFileSelect = function () {
        var list = c.visibleFiles();
        c.allSelected = list.length > 0 && list.every(function (f) { return f._selected; });
    };

    c.clearSelection = function () { _clearSelection(); };

    /* ===================================================
       STORAGE VIEW HELPER
    =================================================== */
    c.storagePct = function (row) {
        var total = (c.data && c.data.storage && c.data.storage.totalBytes) || 0;
        if (!total) return 0;
        return Math.round((row.totalBytes / total) * 100);
    };

    /* ===================================================
       CONTEXT MENU
    =================================================== */

    c.openContextMenu = function (e, item, type) {
        e.preventDefault();
        e.stopPropagation();
        if (c.pickerMode) return;

        var x = e.clientX || 0, y = e.clientY || 0;
        var menuWidth = 200, menuHeight = 260;
        if (x + menuWidth > window.innerWidth) x = window.innerWidth - menuWidth - 10;
        if (y + menuHeight > window.innerHeight) y = window.innerHeight - menuHeight - 10;

        c.contextMenu = { show: true, x: x, y: y, item: item, type: type };
    };

    c.closeContextMenu = function () {
        if (c.contextMenu.show) { c.contextMenu.show = false; c.contextMenu.item = null; }
    };

    /** Three-dot button: opens the same menu anchored to the button */
    c.openMenuFromButton = function ($event, item, type) {
        $event.preventDefault();
        $event.stopPropagation();
        if (c.pickerMode || !item) return;

        if (c.contextMenu.show && c.contextMenu.item === item) { c.closeContextMenu(); return; }

        var rect = ($event.currentTarget || $event.target).getBoundingClientRect();
        var menuWidth = 200, menuHeight = 260;

        var x = rect.right - menuWidth;
        var y = rect.bottom + 4;
        if (x < 10) x = 10;
        if (y + menuHeight > window.innerHeight) y = rect.top - menuHeight - 4;
        if (y < 10) y = 10;

        c.contextMenu = { show: true, x: x, y: y, item: item, type: type };
    };

    /* ===================================================
       FORMAT BYTES
    =================================================== */

    c.formatBytes = function (bytes) {
        bytes = parseInt(bytes, 10) || 0;
        if (bytes === 0) return '0 B';
        if (bytes < 1024) return bytes + ' B';
        if (bytes < 1048576) return (bytes / 1024).toFixed(1) + ' KB';
        if (bytes < 1073741824) return (bytes / 1048576).toFixed(1) + ' MB';
        return (bytes / 1073741824).toFixed(2) + ' GB';
    };

    /* ===================================================
       KEYBOARD (document-level listener is attached in api.link)
         /        focus search
         Ctrl+A   select all files in the current list
         Delete   move selected files to the bin
         ← / →    previous / next image in the preview
         Esc      close the top-most dialog / menu / search
    =================================================== */

    c.anyModalOpen = function () {
        return !!(c.showFolderModal || c.showShareModal || c.showEditFileModal || c.showRenameFileModal ||
            c.showUploadFolderPicker || c.showAddToFolderModal || c.showNicknameModal || c.confirmModal.show || c.previewFile);
    };

    c.onKeyDown = function (e) {
        var key = e.key || '';
        var tag = ((e.target && e.target.tagName) || '').toLowerCase();
        var typing = tag === 'input' || tag === 'textarea' || tag === 'select';

        if (key === 'Escape' || e.keyCode === 27) {
            if (c.contextMenu.show) { c.closeContextMenu(); return; }
            if (c.previewFile) { c.closePreview(); return; }
            if (c.showNicknameModal) { c.cancelNicknameUpload(); return; }
            if (c.confirmModal.show) { c.confirmModal.show = false; return; }
            if (c.showAddToFolderModal) { c.closeAddToFolder(); return; }
            if (c.showRenameFileModal) { c.showRenameFileModal = false; return; }
            if (c.showEditFileModal) { c.showEditFileModal = false; return; }
            if (c.showShareModal) { c.showShareModal = false; return; }
            if (c.showFolderModal) { c.closeFolderModal(); return; }
            if (c.showUploadFolderPicker) { c.showUploadFolderPicker = false; return; }
            if (typing && e.target.id === 'fmSearch') { c.searchText = ''; e.target.blur(); return; }
            if (c.selectedCount() > 0) { c.clearSelection(); return; }
            return;
        }

        if (c.previewFile) {
            if (key === 'ArrowLeft') { c.previewStep(-1); e.preventDefault(); }
            if (key === 'ArrowRight') { c.previewStep(1); e.preventDefault(); }
            return;
        }

        if (typing || c.anyModalOpen()) return;

        if (key === '/' || ((e.ctrlKey || e.metaKey) && (key === 'k' || key === 'K'))) {
            var s = document.getElementById('fmSearch');
            if (s) { s.focus(); e.preventDefault(); }
        } else if ((e.ctrlKey || e.metaKey) && (key === 'a' || key === 'A')) {
            if (c.visibleFiles().length) { c.selectAllVisible(); e.preventDefault(); }
        } else if (key === 'Delete' && !c.pickerMode) {
            if (c.selectedCount() > 0 && c.canDeleteSelected()) { c.confirmDeleteSelected(); e.preventDefault(); }
        }
    };

    /* ===================================================
       PRIVATE HELPERS
    =================================================== */

    function _clearAlerts() { c.message = ''; c.error = ''; c.undo = null; }

    function _clearSelection() {
        c.allSelected = false;
        ((c.data && c.data.files) || []).forEach(function (f) { f._selected = false; });
        ((c.data && c.data.sharedFiles) || []).forEach(function (f) { f._selected = false; });
    }

    /* ===================================================
       BROWSER BACK / FORWARD
    =================================================== */

    function _navKey(s) { return (s.view || '') + '|' + (s.homeSubView || '') + '|' + (s.currentFolder || ''); }

    function _navSnapshot() {
        return {
            view: c.view, homeSubView: c.homeSubView,
            currentFolder: c.currentFolder, currentFolderName: c.currentFolderName,
            breadcrumb: angular.copy(c.breadcrumb)
        };
    }

    var _lastNavKey = _navKey(_navSnapshot());

    function _applyNavSnapshot(s) {
        _lastNavKey = _navKey(s);
        c.view = s.view || 'home';
        c.homeSubView = s.homeSubView || '';
        c.currentFolder = s.currentFolder || '';
        c.currentFolderName = s.currentFolderName || '';
        c.breadcrumb = angular.copy(s.breadcrumb || []);
        c.searchText = '';
        _clearAlerts();
        _clearSelection();
        c.closeContextMenu();
        c.previewFile = null;
    }

    if (!c.pickerMode && window.history && history.pushState) {
        try {
            var _base = angular.extend({}, history.state || {}, { fmNav: _navSnapshot() });
            history.replaceState(_base, document.title, window.location.href);
        } catch (e) { }

        $scope.$watch(function () { return _navKey(c); }, function (key) {
            if (key === _lastNavKey) return;
            _lastNavKey = key;
            try {
                var st = angular.extend({}, history.state || {}, { fmNav: _navSnapshot() });
                history.pushState(st, document.title, window.location.href);
            } catch (e) { }
        });

        var _onPopState = function (ev) {
            var st = ev && ev.state;
            if (st && st.fmNav) $scope.$evalAsync(function () { _applyNavSnapshot(st.fmNav); });
        };
        window.addEventListener('popstate', _onPopState);
        $scope.$on('$destroy', function () { window.removeEventListener('popstate', _onPopState); });
    }
};

/* =====================================================
   LINK FUNCTION
   1. File inputs (no more inline onchange / .scope() calls)
   2. Right-click context menu (items are looked up by id)
   3. Drag & drop: upload zone + drop onto folder cards
   4. Document-level keyboard shortcuts
   5. Close context menu on scroll / resize
===================================================== */
api.link = function ($scope, element) {
    var rootEl = element[0];

    function safeApply(fn) {
        if ($scope.$$phase || ($scope.$root && $scope.$root.$$phase)) { if (fn) fn(); }
        else $scope.$apply(fn);
    }

    /* 1. File inputs */
    rootEl.addEventListener('change', function (e) {
        var t = e.target;
        var kind = t && t.getAttribute && t.getAttribute('data-fm-input');
        if (!kind) return;

        var files = Array.prototype.slice.call(t.files || []);   // copy BEFORE clearing the input
        t.value = '';
        if (!files.length) return;

        safeApply(function () {
            var c = $scope.c;
            if (kind === 'folder') c.onFolderUploadSelected(files);
            else if (kind === 'direct') c.onDirectFilesSelected(files);
            else if (kind === 'picker') c.onPickerFilesSelected(files);
        });
    });

    /* 2. Right-click */
    rootEl.addEventListener('contextmenu', function (ev) {
        var target = ev.target.closest('[fm-context-id]');
        if (!target) return;
        ev.preventDefault();

        var type = target.getAttribute('fm-context-type');
        var id = target.getAttribute('fm-context-id');
        safeApply(function () {
            var item = $scope.c.findItem(type, id);
            if (item) $scope.c.openContextMenu(ev, item, type);
        });
    });

    /* 3. Drag & drop */
    function hasFiles(e) {
        var types = e.dataTransfer && e.dataTransfer.types;
        if (!types) return false;
        for (var i = 0; i < types.length; i++) if (types[i] === 'Files') return true;
        return false;
    }
    function prevent(e) { e.preventDefault(); e.stopPropagation(); }
    function dropFolderOf(e) {
        var el = e.target.closest && e.target.closest('[fm-drop-folder]');
        return (el && el.getAttribute('fm-drop-folder')) ? el : null;
    }

    rootEl.addEventListener('dragover', function (e) {
        if (!hasFiles(e)) return;
        var zone = e.target.closest('[fm-drop-zone]');
        var card = dropFolderOf(e);
        e.preventDefault();                                // also stops the browser opening the file
        if (zone || card) {
            e.stopPropagation();
            e.dataTransfer.dropEffect = 'copy';
            if (zone) safeApply(function () { $scope.c.dragOver = true; });
            if (card) card.classList.add('fm-drag-over');
        }
    });

    rootEl.addEventListener('dragleave', function (e) {
        var zone = e.target.closest('[fm-drop-zone]');
        if (zone && !zone.contains(e.relatedTarget)) safeApply(function () { $scope.c.dragOver = false; });
        var card = dropFolderOf(e);
        if (card && !card.contains(e.relatedTarget)) card.classList.remove('fm-drag-over');
    });

    rootEl.addEventListener('drop', function (e) {
        if (!hasFiles(e)) return;
        e.preventDefault();

        var zone = e.target.closest('[fm-drop-zone]');
        var card = dropFolderOf(e);
        var files = e.dataTransfer && e.dataTransfer.files;

        if (card) {
            prevent(e);
            card.classList.remove('fm-drag-over');
            var folderId = card.getAttribute('fm-drop-folder');
            if (files && files.length) safeApply(function () { $scope.c.uploadToFolder(files, folderId); });
        } else if (zone) {
            prevent(e);
            safeApply(function () { $scope.c.dragOver = false; });
            if (files && files.length && $scope.c.currentFolder && $scope.c.currentFolderCanEdit()) {
                safeApply(function () { $scope.c.onDirectFilesSelected(files); });
            }
        }
    });

    /* 4. Keyboard shortcuts */
    function onDocKey(e) { if ($scope.c) safeApply(function () { $scope.c.onKeyDown(e); }); }
    document.addEventListener('keydown', onDocKey);

    /* 5. Close menu on scroll / resize */
    function closeMenuOnScroll() {
        if ($scope.c && $scope.c.contextMenu && $scope.c.contextMenu.show) {
            safeApply(function () { $scope.c.closeContextMenu(); });
        }
    }
    window.addEventListener('scroll', closeMenuOnScroll, true);
    window.addEventListener('resize', closeMenuOnScroll);

    $scope.$on('$destroy', function () {
        document.removeEventListener('keydown', onDocKey);
        window.removeEventListener('scroll', closeMenuOnScroll, true);
        window.removeEventListener('resize', closeMenuOnScroll);
    });
};

sp_widget.css:
/* =========================================================
   FILE MANAGER — LIGHT PROFESSIONAL THEME
   ServiceNow Service Portal widget CSS (drop-in replacement)
   Same class names as before: no HTML changes required.
========================================================= */

/* ---------- Design tokens ---------- */
.fm-app {
    --fm-bg: #f6f8fc;
    --fm-surface: #ffffff;
    --fm-surface-2: #f8fafc;
    --fm-border: #e6ebf2;
    --fm-border-strong: #d5dde8;
    --fm-text: #1f2a3d;
    --fm-text-strong: #0f1b2d;
    --fm-muted: #64748b;
    --fm-faint: #94a3b8;
    --fm-primary: #2563eb;
    --fm-primary-600: #1d4ed8;
    --fm-primary-50: #eff4ff;
    --fm-primary-100: #dbe7ff;
    --fm-success: #16a34a;
    --fm-danger: #dc2626;
    --fm-radius: 12px;
    --fm-radius-lg: 16px;
    --fm-shadow-sm: 0 1px 2px rgba(16, 24, 40, 0.05);
    --fm-shadow: 0 4px 14px rgba(16, 24, 40, 0.06);
    --fm-shadow-lg: 0 14px 36px rgba(16, 24, 40, 0.12);
    --fm-ease: cubic-bezier(0.2, 0.7, 0.2, 1);
}

/* ---------- Base ---------- */
.fm-app {
    display: flex;
    width: 100%;
    min-height: 800px;
    background: var(--fm-bg);
    color: var(--fm-text);
    font-family: "Inter", -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
    position: relative;
    box-sizing: border-box;
    -webkit-font-smoothing: antialiased;
}

.fm-app * {
    box-sizing: border-box;
}

.fm-app button,
.fm-app input,
.fm-app select,
.fm-app textarea {
    font-family: inherit;
}

/* Keyboard focus ring everywhere */
.fm-app a:focus-visible,
.fm-app button:focus-visible,
.fm-app select:focus-visible,
.fm-app input:focus-visible,
.fm-app tr:focus-visible,
.fm-app [tabindex]:focus-visible {
    outline: 2px solid var(--fm-primary);
    outline-offset: 2px;
}

/* Soft scrollbars */
.fm-app ::-webkit-scrollbar {
    width: 8px;
    height: 8px;
}

.fm-app ::-webkit-scrollbar-thumb {
    background: #d3dbe7;
    border-radius: 9999px;
}

.fm-app ::-webkit-scrollbar-thumb:hover {
    background: #b8c4d4;
}

/* ---------- Picker mode ---------- */
.fm-picker .fm-toolbar-actions,
.fm-picker .fm-card-menu,
.fm-picker .fm-context-menu,
.fm-picker .fm-empty .fm-button,
.fm-picker .fm-more-btn,
.fm-picker .fm-drop-zone {
    display: none !important;
}

.fm-picker .fm-table tbody tr {
    cursor: pointer;
    user-select: none;
}

.fm-picker-banner {
    margin: 0 0 16px;
    padding: 12px 18px;
    background: var(--fm-primary-50);
    border: 1px solid var(--fm-primary-100);
    border-radius: var(--fm-radius);
    font-size: 13px;
    color: var(--fm-primary-600);
    display: flex;
    align-items: center;
    gap: 10px;
    font-weight: 500;
}

/* =========================================================
   SIDEBAR (light)
========================================================= */
.fm-sidebar {
    width: 250px;
    min-width: 250px;
    background: var(--fm-surface);
    color: var(--fm-muted);
    display: flex;
    flex-direction: column;
    min-height: 800px;
    flex-shrink: 0;
    position: relative;
    border-right: 1px solid var(--fm-border);
}

.fm-logo {
    height: 76px;
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 0 22px;
    font-size: 18px;
    font-weight: 700;
    color: var(--fm-text-strong);
    cursor: pointer;
    user-select: none;
    letter-spacing: -0.2px;
}

.fm-logo-icon {
    width: 38px;
    height: 38px;
    border-radius: 11px;
    display: flex;
    align-items: center;
    justify-content: center;
    background: linear-gradient(135deg, #3b82f6 0%, #2563eb 100%);
    color: #fff;
    font-size: 17px;
    flex-shrink: 0;
    box-shadow: 0 4px 12px rgba(37, 99, 235, 0.28);
    transition: transform 0.3s var(--fm-ease);
}

.fm-logo:hover .fm-logo-icon {
    transform: rotate(-8deg) scale(1.06);
}

/* Privacy segmented switch */
.fm-privacy-switch {
    margin: 0 16px 14px;
    padding: 3px;
    background: #eef2f8;
    border: 1px solid var(--fm-border);
    border-radius: 9999px;
    display: flex;
    gap: 3px;
}

.fm-privacy-btn {
    flex: 1;
    height: 32px;
    border: none;
    background: transparent;
    color: var(--fm-muted);
    font-size: 12px;
    font-weight: 600;
    border-radius: 9999px;
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 6px;
    transition: all 0.2s var(--fm-ease);
}

.fm-privacy-btn:hover {
    color: var(--fm-text-strong);
}

.fm-privacy-btn.active {
    background: #fff;
    color: var(--fm-primary-600);
    box-shadow: 0 1px 4px rgba(16, 24, 40, 0.12);
}

.fm-privacy-btn.public.active {
    background: #dcfce7;
    color: #15803d;
    box-shadow: 0 1px 4px rgba(22, 163, 74, 0.2);
}

.fm-check-mark {
    font-size: 10px;
    margin-left: 2px;
}

/* Menu */
.fm-menu {
    padding: 10px 14px;
    flex: 1;
}

.fm-menu-label {
    color: var(--fm-faint);
    font-size: 11px;
    font-weight: 700;
    letter-spacing: 0.9px;
    padding: 0 14px;
    margin-bottom: 8px;
    text-transform: uppercase;
}

.fm-menu-spaced {
    margin-top: 22px;
}

.fm-menu a {
    position: relative;
    display: flex;
    align-items: center;
    gap: 12px;
    height: 42px;
    padding: 0 14px;
    margin-bottom: 3px;
    border-radius: 10px;
    color: var(--fm-muted);
    font-size: 13px;
    font-weight: 500;
    text-decoration: none;
    cursor: pointer;
    transition: background 0.18s ease, color 0.18s ease, transform 0.18s var(--fm-ease);
    user-select: none;
}

.fm-menu a i {
    width: 20px;
    font-size: 15px;
    text-align: center;
    flex-shrink: 0;
    transition: transform 0.18s var(--fm-ease);
}

.fm-menu a:hover {
    background: #f1f5fb;
    color: var(--fm-text-strong);
}

.fm-menu a:hover i {
    transform: scale(1.12);
}

.fm-menu a:active {
    transform: scale(0.98);
}

.fm-menu a.active {
    background: var(--fm-primary-50);
    color: var(--fm-primary-600);
    font-weight: 600;
}

.fm-menu a.active::before {
    content: "";
    position: absolute;
    left: -14px;
    top: 9px;
    bottom: 9px;
    width: 3px;
    border-radius: 0 3px 3px 0;
    background: var(--fm-primary);
}

.fm-menu a.active i {
    color: var(--fm-primary);
}

/* Count pills & badge */
.fm-count-pill {
    margin-left: auto;
    padding: 2px 8px;
    border-radius: 9999px;
    background: #eef2f8;
    color: var(--fm-muted);
    font-size: 11px;
    font-weight: 600;
}

.fm-menu a.active .fm-count-pill {
    background: #fff;
    color: var(--fm-primary-600);
}

.fm-badge {
    margin-left: auto;
    min-width: 20px;
    height: 20px;
    padding: 0 6px;
    border-radius: 10px;
    background: #fee2e2;
    color: #b91c1c;
    font-size: 11px;
    font-weight: 700;
    display: flex;
    align-items: center;
    justify-content: center;
}

/* Sidebar storage */
.fm-sidebar-storage {
    margin: 14px 4px 6px;
    padding: 12px 14px;
    border-radius: 12px;
    background: var(--fm-surface-2);
    border: 1px solid var(--fm-border);
    cursor: pointer;
    transition: all 0.18s ease;
}

.fm-sidebar-storage:hover {
    border-color: var(--fm-primary-100);
    background: var(--fm-primary-50);
}

.fm-storage-bar-track {
    width: 100%;
    height: 6px;
    background: #e3e9f2;
    border-radius: 9999px;
    overflow: hidden;
    margin-bottom: 8px;
}

.fm-storage-bar-fill {
    height: 100%;
    border-radius: 9999px;
    background: linear-gradient(90deg, #60a5fa, #2563eb);
    transition: width 0.6s var(--fm-ease);
}

.fm-storage-legend {
    font-size: 11px;
    color: var(--fm-muted);
    font-weight: 500;
}

/* Bottom art */
.fm-sidebar-bottom-art {
    position: relative;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 14px 10px 20px;
    margin-top: auto;
    overflow: hidden;
}

.fm-art-glow {
    position: absolute;
    width: 110px;
    height: 110px;
    border-radius: 50%;
    background: radial-gradient(circle, rgba(96, 165, 250, 0.22) 0%, transparent 70%);
    pointer-events: none;
}

.fm-art-svg {
    width: 110px;
    height: 80px;
    position: relative;
    z-index: 1;
    filter: drop-shadow(0 6px 12px rgba(37, 99, 235, 0.18));
    animation: fm-float 5s ease-in-out infinite;
}

@keyframes fm-float {

    0%,
    100% {
        transform: translateY(0);
    }

    50% {
        transform: translateY(-5px);
    }
}

.fm-sidebar-upload {
    display: none;
}

/* =========================================================
   MAIN
========================================================= */
.fm-main {
    flex: 1;
    min-width: 0;
    padding: 24px 34px 40px;
    background: var(--fm-bg);
    display: flex;
    flex-direction: column;
    position: relative;
}

.fm-main>section {
    animation: fm-view-in 0.28s var(--fm-ease);
}

@keyframes fm-view-in {
    from {
        opacity: 0;
        transform: translateY(6px);
    }

    to {
        opacity: 1;
        transform: none;
    }
}

.fm-loading-bar {
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    height: 3px;
    overflow: hidden;
    background: var(--fm-primary-100);
    z-index: 10;
}

.fm-loading-bar:after {
    content: "";
    position: absolute;
    top: 0;
    bottom: 0;
    width: 35%;
    background: var(--fm-primary);
    animation: fm-load 1s ease-in-out infinite;
}

@keyframes fm-load {
    from {
        left: -35%;
    }

    to {
        left: 100%;
    }
}

/* ---------- Header ---------- */
.fm-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 16px;
    min-height: 52px;
    margin-bottom: 22px;
    flex-wrap: wrap;
}

.fm-header-title h2 {
    margin: 0;
    font-size: 24px;
    font-weight: 700;
    color: var(--fm-text-strong);
    letter-spacing: -0.4px;
}

.fm-header-actions {
    display: flex;
    align-items: center;
    gap: 10px;
    flex-shrink: 0;
}

.fm-search-pill {
    display: flex;
    align-items: center;
    gap: 10px;
    width: 310px;
    height: 42px;
    padding: 0 14px;
    border: 1px solid var(--fm-border);
    border-radius: 9999px;
    background: var(--fm-surface);
    box-shadow: var(--fm-shadow-sm);
    transition: width 0.25s var(--fm-ease), border-color 0.2s, box-shadow 0.2s;
}

.fm-search-pill:hover {
    border-color: var(--fm-border-strong);
}

.fm-search-pill:focus-within {
    border-color: var(--fm-primary);
    box-shadow: 0 0 0 4px rgba(37, 99, 235, 0.12);
    width: 360px;
}

.fm-search-pill i.fa-search {
    color: var(--fm-faint);
    font-size: 13px;
    flex-shrink: 0;
}

.fm-search-pill:focus-within i.fa-search {
    color: var(--fm-primary);
}

.fm-search-pill input {
    width: 100%;
    min-width: 0;
    border: none !important;
    outline: none !important;
    box-shadow: none !important;
    background: transparent;
    font-size: 13px;
    color: var(--fm-text);
}

.fm-search-pill input::placeholder {
    color: var(--fm-faint);
}

.fm-search-clear {
    border: none;
    background: #eef2f8;
    color: var(--fm-muted);
    width: 20px;
    height: 20px;
    border-radius: 50%;
    font-size: 10px;
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
    transition: background 0.15s;
}

.fm-search-clear:hover {
    background: #dfe6f1;
    color: var(--fm-text-strong);
}

.fm-shortcut-badge {
    padding: 3px 7px;
    background: var(--fm-surface-2);
    border: 1px solid var(--fm-border);
    border-radius: 6px;
    font-size: 10px;
    font-weight: 700;
    color: var(--fm-muted);
    white-space: nowrap;
}

.fm-icon-circle-btn {
    width: 42px;
    height: 42px;
    border: 1px solid var(--fm-border);
    border-radius: 50%;
    background: var(--fm-surface);
    color: var(--fm-muted);
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 15px;
    box-shadow: var(--fm-shadow-sm);
    position: relative;
    transition: all 0.18s var(--fm-ease);
}

.fm-icon-circle-btn:hover {
    color: var(--fm-primary);
    background: var(--fm-primary-50);
    border-color: var(--fm-primary-100);
    transform: translateY(-1px);
}

.fm-icon-circle-btn:active {
    transform: scale(0.94);
}

.fm-notif-dot {
    position: absolute;
    top: 9px;
    right: 10px;
    width: 8px;
    height: 8px;
    border-radius: 50%;
    background: #ef4444;
    border: 2px solid #fff;
}

.fm-user-avatar-btn {
    width: 42px;
    height: 42px;
    border-radius: 50%;
    background: linear-gradient(135deg, #6366f1 0%, #8b5cf6 100%);
    color: #fff;
    font-size: 13px;
    font-weight: 700;
    display: flex;
    align-items: center;
    justify-content: center;
    box-shadow: 0 3px 10px rgba(99, 102, 241, 0.25);
    user-select: none;
    cursor: default;
}

.fm-icon-circle-btn.fm-spinning i {
    animation: fm-spin 0.8s linear infinite;
}

@keyframes fm-spin {
    to {
        transform: rotate(360deg);
    }
}

/* ---------- Breadcrumb ---------- */
.fm-breadcrumb {
    display: flex;
    align-items: center;
    gap: 8px;
    margin-bottom: 18px;
    font-size: 13px;
    color: var(--fm-muted);
    flex-wrap: wrap;
}

.fm-breadcrumb a {
    color: var(--fm-primary);
    text-decoration: none;
    cursor: pointer;
    font-weight: 500;
    padding: 2px 6px;
    border-radius: 6px;
    transition: background 0.15s;
}

.fm-breadcrumb a:hover {
    background: var(--fm-primary-50);
}

.fm-breadcrumb-sep {
    color: #c3cddb;
    font-size: 12px;
}

.fm-breadcrumb-current {
    color: var(--fm-text-strong);
    font-weight: 700;
    padding: 2px 6px;
}

/* =========================================================
   HERO + STATS
========================================================= */
.fm-hero-banner {
    display: flex;
    align-items: center;
    justify-content: space-between;
    min-height: 120px;
    padding: 22px 32px;
    border-radius: 18px;
    background: linear-gradient(105deg, #eaf2ff 0%, #f1edff 55%, #fdf0f7 100%);
    border: 1px solid #e3e9f7;
    box-shadow: var(--fm-shadow-sm);
    position: relative;
    overflow: hidden;
}

.fm-hero-content h3 {
    margin: 0 0 6px;
    font-size: 22px;
    font-weight: 700;
    color: var(--fm-text-strong);
    letter-spacing: -0.3px;
}

.fm-hero-content p {
    margin: 0;
    font-size: 13px;
    color: var(--fm-muted);
    font-weight: 500;
}

.fm-hero-graphic {
    width: 220px;
    height: 100px;
    flex-shrink: 0;
    display: flex;
    align-items: center;
    justify-content: flex-end;
}

.fm-hero-graphic svg {
    max-width: 100%;
    max-height: 100%;
}

.fm-stats {
    display: grid;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    gap: 16px;
    margin-top: 20px;
}

.fm-stat-card {
    display: flex;
    align-items: center;
    gap: 14px;
    min-height: 94px;
    padding: 18px 20px;
    border-radius: var(--fm-radius-lg);
    background: var(--fm-surface);
    border: 1px solid var(--fm-border);
    position: relative;
    overflow: hidden;
    box-shadow: var(--fm-shadow-sm);
    transition: transform 0.2s var(--fm-ease), box-shadow 0.2s ease, border-color 0.2s ease;
    cursor: default;
}

.fm-stat-card::after {
    content: "";
    position: absolute;
    left: 0;
    right: 0;
    bottom: 0;
    height: 3px;
    background: var(--accent, var(--fm-primary));
    transform: scaleX(0);
    transform-origin: left;
    transition: transform 0.3s var(--fm-ease);
}

.fm-stat-card.fm-clickable {
    cursor: pointer;
}

.fm-stat-card.fm-clickable:hover {
    transform: translateY(-3px);
    box-shadow: var(--fm-shadow);
    border-color: var(--fm-border-strong);
}

.fm-stat-card.fm-clickable:hover::after {
    transform: scaleX(1);
}

.fm-stat-card.fm-clickable:active {
    transform: translateY(-1px) scale(0.99);
}

.fm-stat-card.card-blue {
    --accent: #3b82f6;
    background: linear-gradient(135deg, #ffffff 40%, #f0f7ff 100%);
}

.fm-stat-card.card-purple {
    --accent: #8b5cf6;
    background: linear-gradient(135deg, #ffffff 40%, #f6f1ff 100%);
}

.fm-stat-card.card-green {
    --accent: #22c55e;
    background: linear-gradient(135deg, #ffffff 40%, #effcf4 100%);
}

.fm-stat-card.card-orange {
    --accent: #f59e0b;
    background: linear-gradient(135deg, #ffffff 40%, #fff8eb 100%);
}

.fm-stat-icon {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 44px;
    height: 44px;
    min-width: 44px;
    border-radius: 12px;
    font-size: 18px;
    flex-shrink: 0;
    transition: transform 0.25s var(--fm-ease);
}

.fm-stat-card:hover .fm-stat-icon {
    transform: scale(1.08) rotate(-4deg);
}

.fm-stat-icon.blue {
    background: #dbeafe;
    color: #2563eb;
}

.fm-stat-icon.purple {
    background: #ede9fe;
    color: #7c3aed;
}

.fm-stat-icon.green {
    background: #dcfce7;
    color: #16a34a;
}

.fm-stat-icon.orange {
    background: #fef3c7;
    color: #d97706;
}

.fm-stat-text {
    flex: 1;
    min-width: 0;
}

.fm-stat-text span {
    display: block;
    color: var(--fm-muted);
    font-size: 12px;
    font-weight: 600;
    margin-bottom: 2px;
}

.fm-stat-text strong {
    display: block;
    color: var(--fm-text-strong);
    font-size: 26px;
    font-weight: 700;
    letter-spacing: -0.5px;
}

.fm-stat-decor {
    width: 52px;
    height: 44px;
    flex-shrink: 0;
    display: flex;
    align-items: center;
    justify-content: center;
    opacity: 0.8;
}

.fm-stat-decor svg {
    width: 100%;
    height: 100%;
}

/* ---------- Recent ---------- */
.fm-recent-section {
    margin-top: 28px;
}

.fm-recent-header-bar {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin-bottom: 14px;
}

.fm-recent-title {
    display: flex;
    align-items: center;
    gap: 8px;
    color: var(--fm-text-strong);
}

.fm-recent-title i {
    font-size: 16px;
    color: var(--fm-primary);
}

.fm-recent-title h4,
.fm-recent-header-bar h4 {
    margin: 0;
    font-size: 16px;
    font-weight: 700;
    color: var(--fm-text-strong);
    letter-spacing: -0.2px;
}

.fm-view-switch {
    display: flex;
    align-items: center;
    gap: 3px;
    background: var(--fm-surface);
    border: 1px solid var(--fm-border);
    border-radius: 10px;
    padding: 3px;
    box-shadow: var(--fm-shadow-sm);
}

.fm-view-btn {
    width: 32px;
    height: 32px;
    border: none;
    background: transparent;
    border-radius: 8px;
    color: var(--fm-muted);
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 14px;
    transition: all 0.15s;
}

.fm-view-btn:hover {
    color: var(--fm-primary);
    background: var(--fm-surface-2);
}

.fm-view-btn.active {
    background: var(--fm-primary-50);
    color: var(--fm-primary);
}

/* =========================================================
   TABLE
========================================================= */
.fm-table-card {
    background: var(--fm-surface);
    border-radius: var(--fm-radius-lg);
    border: 1px solid var(--fm-border);
    box-shadow: var(--fm-shadow-sm);
    overflow-x: auto;
    overflow-y: hidden;
    width: 100%;
}

.fm-table {
    width: 100%;
    border-collapse: collapse;
    min-width: 580px;
}

.fm-table th {
    padding: 13px 20px;
    text-align: left;
    background: var(--fm-surface-2);
    border-bottom: 1px solid var(--fm-border);
    color: var(--fm-muted);
    font-size: 11px;
    font-weight: 700;
    letter-spacing: 0.5px;
    text-transform: uppercase;
    white-space: nowrap;
    vertical-align: middle;
}

.fm-table th.fm-sortable {
    cursor: pointer;
    user-select: none;
    transition: color 0.15s;
}

.fm-table th.fm-sortable:hover {
    color: var(--fm-primary);
}

.fm-table td {
    padding: 12px 20px;
    border-bottom: 1px solid #f1f4f9;
    color: var(--fm-text);
    font-size: 13px;
    vertical-align: middle;
}

.fm-table tbody tr {
    cursor: pointer;
    transition: background 0.12s ease;
}

.fm-table tbody tr:last-child td {
    border-bottom: none;
}

.fm-table tbody tr:hover {
    background: #f5f8ff;
}

.fm-table tbody tr.fm-row-selected {
    background: var(--fm-primary-50);
    box-shadow: inset 3px 0 0 var(--fm-primary);
}

.fm-table input[type="checkbox"] {
    width: 16px;
    height: 16px;
    accent-color: var(--fm-primary);
    cursor: pointer;
}

/* Actions button appears subtle until row hover */
.fm-table tbody tr .fm-more-btn {
    opacity: 0.55;
}

.fm-table tbody tr:hover .fm-more-btn {
    opacity: 1;
}

.fm-file-cell {
    display: flex;
    align-items: center;
    gap: 12px;
    min-width: 0;
}

.fm-file-icon-box {
    width: 38px;
    height: 38px;
    border-radius: 10px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 17px;
    flex-shrink: 0;
    transition: transform 0.2s var(--fm-ease);
}

tr:hover .fm-file-icon-box,
.fm-file-card:hover .fm-file-card-preview {
    transform: scale(1.07);
}

.fm-file-title {
    font-weight: 600;
    color: var(--fm-text-strong);
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    max-width: 320px;
}

.fm-text-muted {
    color: var(--fm-muted);
    font-size: 13px;
}

/* File-type colors (table icon + grid preview) */
.fm-icon-image {
    background: #dcfce7;
    color: #16a34a;
}

.fm-icon-pdf {
    background: #fee2e2;
    color: #dc2626;
}

.fm-icon-word {
    background: #dbeafe;
    color: #2563eb;
}

.fm-icon-excel {
    background: #d1fae5;
    color: #059669;
}

.fm-icon-ppt {
    background: #ffedd5;
    color: #ea580c;
}

.fm-icon-zip {
    background: #fef3c7;
    color: #d97706;
}

.fm-icon-audio {
    background: #e0e7ff;
    color: #4f46e5;
}

.fm-icon-video {
    background: #fae8ff;
    color: #c026d3;
}

.fm-icon-code {
    background: #f3e8ff;
    color: #9333ea;
}

.fm-icon-text {
    background: #f1f5f9;
    color: #475569;
}

.fm-icon-default {
    background: #f1f5f9;
    color: #64748b;
}

/* Three-dots */
.fm-more-btn {
    width: 34px;
    height: 34px;
    border: 1px solid transparent;
    border-radius: 50%;
    background: transparent;
    color: var(--fm-muted);
    font-size: 15px;
    cursor: pointer;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    transition: all 0.15s ease;
}

.fm-more-btn:hover {
    background: var(--fm-primary-50);
    border-color: var(--fm-primary-100);
    color: var(--fm-primary);
}

.fm-more-btn:active {
    transform: scale(0.92);
}

/* =========================================================
   CONTEXT MENU
========================================================= */
.fm-context-menu {
    position: fixed;
    z-index: 99999;
    min-width: 210px;
    background: var(--fm-surface);
    border: 1px solid var(--fm-border);
    border-radius: 12px;
    box-shadow: var(--fm-shadow-lg);
    padding: 6px;
    animation: fm-pop-in 0.14s var(--fm-ease);
    transform-origin: top left;
}

@keyframes fm-pop-in {
    from {
        opacity: 0;
        transform: scale(0.95) translateY(-4px);
    }

    to {
        opacity: 1;
        transform: none;
    }
}

.fm-context-item {
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 9px 12px;
    font-size: 13px;
    font-weight: 500;
    color: var(--fm-text);
    border-radius: 8px;
    cursor: pointer;
    transition: background 0.12s ease, color 0.12s ease, padding-left 0.15s var(--fm-ease);
}

.fm-context-item i {
    width: 16px;
    font-size: 14px;
    text-align: center;
    color: var(--fm-muted);
    transition: color 0.12s;
}

.fm-context-item:hover {
    background: var(--fm-primary-50);
    color: var(--fm-primary-600);
    padding-left: 15px;
}

.fm-context-item:hover i {
    color: var(--fm-primary);
}

.fm-context-item.danger,
.fm-context-item.danger i {
    color: var(--fm-danger);
}

.fm-context-item.danger:hover {
    background: #fef2f2;
    color: #b91c1c;
}

.fm-context-divider {
    height: 1px;
    background: var(--fm-border);
    margin: 4px 6px;
}

/* =========================================================
   GRID VIEWS
========================================================= */
.fm-file-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
    gap: 14px;
}

.fm-file-card {
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 12px 14px;
    border-radius: 14px;
    background: var(--fm-surface);
    border: 1px solid var(--fm-border);
    box-shadow: var(--fm-shadow-sm);
    cursor: pointer;
    position: relative;
    transition: transform 0.2s var(--fm-ease), box-shadow 0.2s ease, border-color 0.2s ease;
}

.fm-file-card:hover {
    border-color: var(--fm-primary-100);
    transform: translateY(-3px);
    box-shadow: var(--fm-shadow);
}

.fm-file-card.fm-row-selected {
    border-color: var(--fm-primary);
    background: var(--fm-primary-50);
}

.fm-file-card-preview {
    width: 42px;
    height: 42px;
    border-radius: 10px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 18px;
    flex-shrink: 0;
    transition: transform 0.2s var(--fm-ease);
}

.fm-file-card-info {
    flex: 1;
    min-width: 0;
    display: flex;
    flex-direction: column;
    gap: 2px;
}

.fm-file-card-info strong {
    font-size: 13px;
    color: var(--fm-text-strong);
    font-weight: 600;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.fm-file-card-info span {
    font-size: 11px;
    color: var(--fm-muted);
}

.fm-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(250px, 1fr));
    gap: 14px;
}

.fm-folder-card {
    position: relative;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
    min-height: 84px;
    padding: 14px 16px;
    border: 1px solid var(--fm-border);
    border-radius: 14px;
    background: var(--fm-surface);
    box-shadow: var(--fm-shadow-sm);
    transition: transform 0.2s var(--fm-ease), box-shadow 0.2s ease, border-color 0.2s ease, background 0.2s;
}

.fm-folder-card:hover {
    border-color: var(--fm-primary-100);
    box-shadow: var(--fm-shadow);
    transform: translateY(-3px);
}

.fm-folder-card.fm-drag-over {
    border: 2px dashed var(--fm-primary);
    background: var(--fm-primary-50);
    box-shadow: 0 0 0 4px rgba(37, 99, 235, 0.12);
    transform: scale(1.02);
}

.fm-folder-main {
    display: flex;
    align-items: center;
    gap: 12px;
    flex: 1;
    min-width: 0;
    cursor: pointer;
}

.fm-folder-icon {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 44px;
    height: 44px;
    min-width: 44px;
    border-radius: 12px;
    background: #fff7e6;
    color: #f59e0b;
    font-size: 20px;
    transition: transform 0.25s var(--fm-ease);
}

.fm-folder-card:hover .fm-folder-icon {
    transform: scale(1.08) rotate(-4deg);
}

.fm-folder-icon.fm-color-orange {
    background: #fff4de;
    color: #f59e0b;
}

.fm-folder-icon.fm-color-blue {
    background: #e5efff;
    color: #3b82f6;
}

.fm-folder-icon.fm-color-purple {
    background: #efeaff;
    color: #8b5cf6;
}

.fm-folder-icon.fm-color-green {
    background: #def7ea;
    color: #10b981;
}

.fm-folder-icon.fm-color-pink {
    background: #fde7f3;
    color: #ec4899;
}

.fm-color-text-orange {
    color: #f59e0b !important;
}

.fm-color-text-blue {
    color: #3b82f6 !important;
}

.fm-color-text-purple {
    color: #8b5cf6 !important;
}

.fm-color-text-green {
    color: #10b981 !important;
}

.fm-color-text-pink {
    color: #ec4899 !important;
}

.fm-folder-chip.fm-chip-orange {
    background: #fff4de;
    color: #b45309;
}

.fm-folder-chip.fm-chip-blue {
    background: #e5efff;
    color: #1d4ed8;
}

.fm-folder-chip.fm-chip-purple {
    background: #efeaff;
    color: #6d28d9;
}

.fm-folder-chip.fm-chip-green {
    background: #def7ea;
    color: #047857;
}

.fm-folder-chip.fm-chip-pink {
    background: #fde7f3;
    color: #be185d;
}

.fm-card-info {
    display: flex;
    flex-direction: column;
    min-width: 0;
    gap: 3px;
}

.fm-card-info strong {
    color: var(--fm-text-strong);
    font-size: 13px;
    font-weight: 700;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.fm-card-info span {
    color: var(--fm-muted);
    font-size: 11px;
}

.fm-card-menu {
    display: flex;
    gap: 4px;
    flex-shrink: 0;
}

.fm-folder-chip {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    padding: 4px 10px;
    background: #fff4de;
    color: #b45309;
    border-radius: 8px;
    font-size: 12px;
    font-weight: 600;
    cursor: pointer;
    max-width: 180px;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    transition: filter 0.15s, transform 0.15s;
}

.fm-folder-chip:hover {
    filter: brightness(0.96);
    transform: translateY(-1px);
}

/* Folder color picker */
.fm-color-picker {
    display: flex;
    align-items: center;
    gap: 8px;
    margin: 8px 0 16px;
    flex-wrap: wrap;
}

.fm-color-pill {
    display: inline-flex;
    align-items: center;
    gap: 7px;
    padding: 6px 12px;
    border-radius: 9999px;
    background: var(--fm-surface-2);
    border: 1px solid var(--fm-border);
    cursor: pointer;
    transition: all 0.15s ease;
    user-select: none;
    font-size: 12px;
    font-weight: 500;
    color: #475569;
}

.fm-color-pill:hover {
    background: #f1f5f9;
    border-color: var(--fm-border-strong);
    transform: translateY(-1px);
}

.fm-color-pill.selected {
    background: #fff;
    border-color: var(--fm-primary);
    box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.15);
    color: var(--fm-text-strong);
    font-weight: 600;
}

.fm-color-circle {
    width: 16px;
    height: 16px;
    border-radius: 50%;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
}

.fm-color-circle i {
    color: #fff;
    font-size: 8px;
}

.fm-color-name {
    line-height: 1;
}

/* =========================================================
   BUTTONS & TOOLBARS
========================================================= */
.fm-button {
    position: relative;
    overflow: hidden;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 8px;
    min-height: 38px;
    padding: 8px 16px;
    border: 1px solid var(--fm-border-strong);
    border-radius: 10px;
    background: var(--fm-surface);
    color: #475569;
    font-size: 13px;
    font-weight: 600;
    cursor: pointer;
    text-decoration: none;
    white-space: nowrap;
    box-shadow: var(--fm-shadow-sm);
    transition: background 0.15s, color 0.15s, border-color 0.15s, transform 0.15s var(--fm-ease), box-shadow 0.15s;
}

.fm-button:hover {
    background: var(--fm-surface-2);
    color: var(--fm-primary);
    border-color: var(--fm-primary-100);
    transform: translateY(-1px);
    box-shadow: var(--fm-shadow);
}

.fm-button:active {
    transform: translateY(0) scale(0.98);
}

.fm-button.fm-primary {
    color: #fff;
    background: linear-gradient(180deg, #3b82f6 0%, #2563eb 100%);
    border-color: #2563eb;
    box-shadow: 0 2px 8px rgba(37, 99, 235, 0.28);
}

.fm-button.fm-primary:hover {
    background: linear-gradient(180deg, #4b8df8 0%, #1d4ed8 100%);
    color: #fff;
    box-shadow: 0 6px 16px rgba(37, 99, 235, 0.32);
}

.fm-button.fm-danger {
    color: #b91c1c;
    background: #fef2f2;
    border-color: #fecaca;
    box-shadow: none;
}

.fm-button.fm-danger:hover {
    background: #fee2e2;
    border-color: #fca5a5;
    color: #991b1b;
}

.fm-button.fm-danger-solid {
    color: #fff;
    background: var(--fm-danger);
    border-color: var(--fm-danger);
}

.fm-button.fm-danger-solid:hover {
    background: #b91c1c;
    color: #fff;
}

.fm-button:disabled,
.fm-button[disabled],
.fm-disabled {
    opacity: 0.5;
    cursor: not-allowed;
    pointer-events: none;
}

.fm-back-btn {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    padding: 4px 8px 4px 0;
    margin-bottom: 8px;
    border: none;
    background: transparent;
    color: var(--fm-primary);
    font-size: 13px;
    font-weight: 600;
    cursor: pointer;
}

.fm-back-btn i {
    transition: transform 0.18s var(--fm-ease);
}

.fm-back-btn:hover i {
    transform: translateX(-4px);
}

.fm-toolbar {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 16px;
    margin-bottom: 18px;
    flex-wrap: wrap;
}

.fm-toolbar p {
    margin: 0;
    font-size: 13px;
    color: var(--fm-muted);
}

.fm-toolbar-actions {
    display: flex;
    align-items: center;
    gap: 10px;
    flex-wrap: wrap;
}

.fm-type-filter {
    height: 38px;
    padding: 0 12px;
    border: 1px solid var(--fm-border-strong);
    border-radius: 10px;
    background: var(--fm-surface);
    font-size: 12px;
    color: #475569;
    cursor: pointer;
    transition: border-color 0.15s;
}

.fm-type-filter:hover {
    border-color: var(--fm-primary);
}

.fm-subsection {
    margin-top: 24px;
}

.fm-subsection h4 {
    font-size: 15px;
    font-weight: 700;
    margin: 0 0 14px;
    color: var(--fm-text-strong);
}

.fm-section {
    margin-top: 24px;
}

.fm-section-header h3 {
    margin: 0 0 12px;
    font-size: 16px;
    font-weight: 700;
    color: var(--fm-text-strong);
}

/* =========================================================
   DROP ZONE, UPLOAD, EMPTY, SELECTION
========================================================= */
.fm-drop-zone {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 12px;
    height: 64px;
    margin-bottom: 18px;
    border: 2px dashed var(--fm-border-strong);
    border-radius: 14px;
    color: var(--fm-muted);
    font-size: 13px;
    background: var(--fm-surface);
    transition: all 0.2s ease;
}

.fm-drop-zone i {
    font-size: 24px;
    color: var(--fm-primary);
    transition: transform 0.25s var(--fm-ease);
}

.fm-drop-zone:hover {
    border-color: #93b4f5;
    background: #fafcff;
}

.fm-drop-zone.fm-drag-over {
    border-color: var(--fm-primary);
    background: var(--fm-primary-50);
    color: var(--fm-primary-600);
}

.fm-drop-zone.fm-drag-over i {
    transform: translateY(-4px) scale(1.15);
}

.fm-upload-progress {
    display: flex;
    align-items: center;
    gap: 12px;
    margin-bottom: 18px;
    padding: 12px 18px;
    background: var(--fm-surface);
    border: 1px solid var(--fm-border);
    border-radius: var(--fm-radius);
    font-size: 13px;
    color: #334155;
    box-shadow: var(--fm-shadow-sm);
}

.fm-upload-bar {
    flex: 1;
    height: 6px;
    background: #eef2f8;
    border-radius: 9999px;
    overflow: hidden;
}

.fm-upload-fill {
    height: 100%;
    border-radius: 9999px;
    transition: width 0.3s ease;
    background: linear-gradient(90deg, #60a5fa, #2563eb, #60a5fa);
    background-size: 200% 100%;
    animation: fm-shimmer 1.4s linear infinite;
}

@keyframes fm-shimmer {
    from {
        background-position: 200% 0;
    }

    to {
        background-position: -200% 0;
    }
}

.fm-empty {
    padding: 48px 20px;
    text-align: center;
    color: var(--fm-faint);
}

.fm-empty>i {
    display: block;
    margin: 0 auto 14px;
    width: 76px;
    height: 76px;
    line-height: 76px;
    border-radius: 50%;
    background: #eef3fb;
    font-size: 32px;
    color: #a9b9d2;
}

.fm-empty p {
    margin: 0 0 14px;
    font-size: 13px;
}

.fm-selection-bar {
    position: sticky;
    bottom: 16px;
    z-index: 5;
    margin-top: 14px;
    display: flex;
    align-items: center;
    gap: 10px;
    flex-wrap: wrap;
    padding: 12px 16px;
    background: var(--fm-surface);
    border: 1px solid var(--fm-primary-100);
    border-radius: 14px;
    box-shadow: var(--fm-shadow-lg);
    animation: fm-rise 0.22s var(--fm-ease);
}

@keyframes fm-rise {
    from {
        opacity: 0;
        transform: translateY(10px);
    }

    to {
        opacity: 1;
        transform: none;
    }
}

.fm-selection-count {
    font-size: 13px;
    color: var(--fm-primary-600);
    font-weight: 700;
    margin-right: auto;
}

/* =========================================================
   ALERTS
========================================================= */
.fm-alert {
    display: flex;
    align-items: center;
    gap: 10px;
    padding: 12px 16px;
    margin-bottom: 18px;
    border-radius: var(--fm-radius);
    font-size: 13px;
    font-weight: 500;
    animation: fm-rise 0.22s var(--fm-ease);
}

.fm-alert span {
    flex: 1;
}

.fm-alert button {
    border: none;
    background: transparent;
    font-size: 20px;
    line-height: 1;
    cursor: pointer;
    color: inherit;
    opacity: 0.55;
    transition: opacity 0.15s;
}

.fm-alert button:hover {
    opacity: 1;
}

.fm-alert .fm-undo-btn {
    font-size: 12px;
    font-weight: 700;
    opacity: 1;
    padding: 4px 10px;
    border: 1px solid currentColor;
    border-radius: 6px;
}

.fm-alert .fm-undo-btn:hover {
    background: rgba(255, 255, 255, 0.6);
}

.fm-alert-success {
    background: #ecfdf3;
    color: #166534;
    border: 1px solid #c6f0d6;
}

.fm-alert-error {
    background: #fef2f2;
    color: #991b1b;
    border: 1px solid #fcd0d0;
}

/* =========================================================
   STORAGE VIEW
========================================================= */
.fm-storage-card {
    display: flex;
    align-items: center;
    gap: 20px;
    padding: 24px 28px;
    border: 1px solid var(--fm-border);
    border-radius: var(--fm-radius-lg);
    background: var(--fm-surface);
    box-shadow: var(--fm-shadow-sm);
    margin-bottom: 20px;
}

.fm-storage-icon {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 54px;
    height: 54px;
    border-radius: 14px;
    background: var(--fm-primary-50);
    color: var(--fm-primary);
    font-size: 24px;
    flex-shrink: 0;
}

.fm-storage-card h3 {
    margin: 0 0 4px;
    font-size: 18px;
    color: var(--fm-text-strong);
    font-weight: 700;
}

.fm-storage-card p {
    margin: 0;
    color: var(--fm-muted);
    font-size: 13px;
}

.fm-storage-note {
    margin-top: 18px;
    color: var(--fm-faint);
    font-size: 12px;
    line-height: 1.6;
}

.fm-ext-badge {
    display: inline-block;
    padding: 4px 10px;
    border-radius: 6px;
    background: #eef2f8;
    color: #475569;
    font-size: 11px;
    font-weight: 700;
    text-transform: uppercase;
}

.fm-usage-track {
    display: inline-block;
    vertical-align: middle;
    width: calc(100% - 52px);
    height: 8px;
    background: #eef2f8;
    border-radius: 9999px;
    overflow: hidden;
}

.fm-usage-fill {
    height: 100%;
    background: linear-gradient(90deg, #60a5fa, #2563eb);
    border-radius: 9999px;
    transition: width 0.6s var(--fm-ease);
}

.fm-usage-pct {
    display: inline-block;
    width: 44px;
    margin-left: 4px;
    font-size: 12px;
    color: var(--fm-muted);
    text-align: right;
    font-weight: 600;
}

/* =========================================================
   PAGINATION, TABS, STATUS, RECYCLE
========================================================= */
.fm-pagination {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 14px;
    flex-wrap: wrap;
    padding: 12px 18px;
    margin-top: 14px;
    border-radius: var(--fm-radius);
    background: var(--fm-surface);
    border: 1px solid var(--fm-border);
    color: var(--fm-muted);
    font-size: 12px;
}

.fm-pagination-controls {
    display: flex;
    align-items: center;
    gap: 6px;
}

.fm-pagination-controls button,
.fm-pagination-controls select {
    min-height: 32px;
    min-width: 32px;
    padding: 4px 10px;
    border: 1px solid var(--fm-border-strong);
    border-radius: 8px;
    background: var(--fm-surface);
    color: #475569;
    font-size: 12px;
    font-weight: 600;
    transition: all 0.15s;
}

.fm-pagination-controls button {
    cursor: pointer;
}

.fm-pagination-controls button:hover:not(:disabled) {
    border-color: var(--fm-primary);
    color: var(--fm-primary);
    background: var(--fm-primary-50);
}

.fm-pagination-controls button:disabled {
    opacity: 0.45;
    cursor: not-allowed;
}

.fm-pagination-controls button.fm-page-active {
    background: var(--fm-primary);
    border-color: var(--fm-primary);
    color: #fff;
}

.fm-tabs {
    display: flex;
    align-items: center;
    gap: 6px;
    padding-bottom: 14px;
    border-bottom: 1px solid var(--fm-border);
    margin-bottom: 16px;
}

.fm-tabs button {
    border: 1px solid transparent;
    border-radius: 10px;
    padding: 8px 16px;
    background: transparent;
    color: var(--fm-muted);
    font-size: 13px;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.15s;
}

.fm-tabs button:hover {
    background: #f1f5f9;
    color: var(--fm-primary);
}

.fm-tabs button.active {
    background: var(--fm-primary-50);
    color: var(--fm-primary-600);
    border-color: var(--fm-primary-100);
}

.fm-status {
    display: inline-block;
    padding: 3px 10px;
    border-radius: 9999px;
    font-size: 11px;
    font-weight: 600;
}

.fm-status.active {
    background: #dcfce7;
    color: #166534;
}

.fm-status.inactive {
    background: #f1f5f9;
    color: #64748b;
}

.fm-restore-btn,
.fm-perm-delete-btn {
    display: inline-flex;
    align-items: center;
    gap: 5px;
    height: 30px;
    padding: 0 12px;
    border-radius: 8px;
    font-size: 12px;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.15s;
    white-space: nowrap;
}

.fm-restore-btn {
    background: #ecfdf3;
    color: #166534;
    border: 1px solid #c6f0d6;
}

.fm-restore-btn:hover {
    background: #d5f5e1;
    transform: translateY(-1px);
}

.fm-perm-delete-btn {
    background: #fef2f2;
    color: #b91c1c;
    border: 1px solid #fcd0d0;
}

.fm-perm-delete-btn:hover {
    background: #fee2e2;
    transform: translateY(-1px);
}

.fm-recycle-actions {
    display: flex;
    align-items: center;
    gap: 8px;
    justify-content: flex-end;
}

/* =========================================================
   MODALS
========================================================= */
.fm-modal-backdrop {
    position: fixed;
    inset: 0;
    z-index: 9999;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 16px;
    background: rgba(30, 41, 59, 0.32);
    backdrop-filter: blur(4px);
    animation: fm-fadein 0.2s ease;
}

@keyframes fm-fadein {
    from {
        opacity: 0;
    }

    to {
        opacity: 1;
    }
}

.fm-modal {
    width: 100%;
    max-width: 480px;
    max-height: 90vh;
    overflow-y: auto;
    padding: 28px;
    border-radius: 20px;
    background: var(--fm-surface);
    box-shadow: 0 30px 70px rgba(16, 24, 40, 0.2);
    border: 1px solid var(--fm-border);
    animation: fm-modal-in 0.24s var(--fm-ease);
}

@keyframes fm-modal-in {
    from {
        opacity: 0;
        transform: translateY(14px) scale(0.97);
    }

    to {
        opacity: 1;
        transform: none;
    }
}

.fm-share-modal {
    max-width: 540px;
}

.fm-confirm-modal {
    max-width: 420px;
}

.fm-confirm-text {
    margin: 0 0 4px;
    font-size: 14px;
    line-height: 1.6;
    color: #475569;
}

.fm-modal-hint {
    margin: 0 0 10px;
    font-size: 13px;
    color: var(--fm-muted);
}

.fm-modal-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin-bottom: 20px;
}

.fm-modal-header h3 {
    margin: 0;
    color: var(--fm-text-strong);
    font-size: 19px;
    font-weight: 700;
    letter-spacing: -0.3px;
}

.fm-modal-header button,
.fm-modal-close {
    width: 32px;
    height: 32px;
    border: none;
    border-radius: 8px;
    background: #f1f5f9;
    color: var(--fm-muted);
    font-size: 18px;
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    line-height: 1;
    transition: all 0.15s ease;
}

.fm-modal-header button:hover,
.fm-modal-close:hover {
    background: #e2e8f0;
    color: var(--fm-text-strong);
    transform: rotate(90deg);
}

.fm-modal-location {
    font-size: 13px;
    color: var(--fm-muted);
    margin-bottom: 18px;
    display: flex;
    align-items: center;
    gap: 6px;
}

.fm-modal-location strong {
    color: var(--fm-text-strong);
}

.fm-form-group {
    position: relative;
    margin-bottom: 18px;
}

.fm-form-group label,
.fm-modal label {
    display: block;
    margin-bottom: 8px;
    color: #334155;
    font-size: 13px;
    font-weight: 600;
}

.fm-optional {
    font-size: 12px;
    font-weight: normal;
    color: var(--fm-faint);
}

.fm-modal input[type="text"],
.fm-modal input[type="datetime-local"],
.fm-modal select,
.fm-modal textarea {
    width: 100%;
    min-height: 42px;
    padding: 10px 14px;
    border: 1.5px solid var(--fm-border);
    border-radius: 10px;
    outline: none;
    background: #fff;
    color: var(--fm-text);
    font-size: 14px;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.fm-modal textarea {
    resize: vertical;
    min-height: 75px;
}

.fm-modal input:hover,
.fm-modal textarea:hover {
    border-color: var(--fm-border-strong);
}

.fm-modal input:focus,
.fm-modal select:focus,
.fm-modal textarea:focus {
    border-color: var(--fm-primary);
    box-shadow: 0 0 0 4px rgba(37, 99, 235, 0.12);
}

.fm-char-count {
    text-align: right;
    font-size: 11px;
    color: var(--fm-faint);
    margin-top: 4px;
}

.fm-modal-actions {
    display: flex;
    justify-content: flex-end;
    gap: 10px;
    margin-top: 24px;
}

.fm-btn-secondary {
    background: #fff !important;
    border: 1.5px solid var(--fm-border) !important;
    color: #475569 !important;
}

.fm-btn-secondary:hover {
    background: var(--fm-surface-2) !important;
    color: var(--fm-text-strong) !important;
}

.fm-share-target {
    padding: 10px 14px;
    background: var(--fm-surface-2);
    border: 1px solid var(--fm-border);
    border-radius: 10px;
    font-size: 13px;
    margin-bottom: 14px;
    display: flex;
    align-items: center;
    gap: 10px;
}

/* Folder picker list */
.fm-folder-picker-list {
    max-height: 220px;
    overflow-y: auto;
    border: 1px solid var(--fm-border);
    border-radius: 10px;
    margin-top: 8px;
    background: #fff;
}

.fm-folder-picker-item {
    display: flex;
    align-items: center;
    gap: 10px;
    padding: 10px 14px;
    cursor: pointer;
    border-bottom: 1px solid #f1f4f9;
    transition: background 0.12s;
}

.fm-folder-picker-item:last-child {
    border-bottom: none;
}

.fm-folder-picker-item:hover {
    background: var(--fm-surface-2);
}

.fm-folder-picker-item.selected {
    background: var(--fm-primary-50);
    color: var(--fm-primary-600);
    font-weight: 600;
}

.fm-folder-picker-item i.fa-folder {
    font-size: 16px;
}

.fm-folder-picker-name {
    flex: 1;
    font-size: 13px;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.fm-folder-picker-check {
    color: var(--fm-primary);
}

.fm-picker-new-link {
    margin-top: 10px;
    font-size: 12px;
    color: var(--fm-primary);
    cursor: pointer;
    display: inline-block;
    font-weight: 600;
}

.fm-picker-new-link:hover {
    text-decoration: underline;
}

/* Share: user & group search */
.fm-user-search {
    display: flex;
    align-items: center;
    gap: 10px;
    padding: 0 12px;
    border: 1.5px solid var(--fm-border);
    border-radius: 10px;
    background: #fff;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.fm-user-search:focus-within {
    border-color: var(--fm-primary);
    box-shadow: 0 0 0 4px rgba(37, 99, 235, 0.12);
}

.fm-user-search i {
    color: var(--fm-faint);
}

.fm-modal .fm-user-search input[type="text"] {
    border: none;
    box-shadow: none !important;
    padding-left: 0;
}

.fm-search-help {
    margin: 6px 0 10px;
    font-size: 11px;
    color: var(--fm-faint);
}

.fm-user-status {
    margin: 8px 0;
    font-size: 12px;
    color: var(--fm-muted);
}

.fm-user-error {
    color: var(--fm-danger);
}

.fm-user-results {
    max-height: 190px;
    overflow-y: auto;
    border: 1px solid var(--fm-border);
    border-radius: 10px;
    margin-bottom: 14px;
}

.fm-user-option {
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 9px 12px;
    cursor: pointer;
    border-bottom: 1px solid #f1f4f9;
    transition: background 0.12s;
}

.fm-user-option:last-child {
    border-bottom: none;
}

.fm-user-option:hover {
    background: var(--fm-surface-2);
}

.fm-user-option.fm-user-selected {
    background: var(--fm-primary-50);
}

.fm-user-avatar {
    width: 32px;
    height: 32px;
    border-radius: 50%;
    background: linear-gradient(135deg, #3b82f6, #6366f1);
    color: #fff;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 12px;
    font-weight: 700;
    flex-shrink: 0;
}

.fm-user-info {
    flex: 1;
    min-width: 0;
    display: flex;
    flex-direction: column;
}

.fm-user-info strong {
    font-size: 13px;
    color: var(--fm-text-strong);
}

.fm-user-info span {
    font-size: 11px;
    color: var(--fm-muted);
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.fm-date-input {
    margin-bottom: 4px;
}

/* Image preview */
.fm-preview-backdrop {
    z-index: 10000;
}

.fm-preview-modal {
    display: flex;
    flex-direction: column;
    width: 100%;
    max-width: 860px;
    max-height: 90vh;
    overflow: hidden;
    border-radius: 18px;
    background: #fff;
    box-shadow: 0 30px 70px rgba(16, 24, 40, 0.25);
    animation: fm-modal-in 0.24s var(--fm-ease);
}

.fm-preview-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 16px;
    padding: 16px 24px;
    border-bottom: 1px solid var(--fm-border);
    color: var(--fm-text-strong);
    font-size: 15px;
    font-weight: 700;
}

.fm-preview-header button {
    width: 32px;
    height: 32px;
    border: none;
    border-radius: 8px;
    background: #f1f5f9;
    color: var(--fm-muted);
    font-size: 20px;
    cursor: pointer;
    transition: background 0.15s;
}

.fm-preview-header button:hover {
    background: #e2e8f0;
}

.fm-preview-content {
    position: relative;
    display: flex;
    align-items: center;
    justify-content: center;
    min-height: 280px;
    max-height: 65vh;
    padding: 24px;
    overflow: auto;
    background: #f4f7fb;
}

.fm-preview-content img {
    display: block;
    max-width: 100%;
    max-height: 60vh;
    object-fit: contain;
    border-radius: 8px;
    box-shadow: var(--fm-shadow);
}

.fm-preview-nav {
    position: absolute;
    top: 50%;
    transform: translateY(-50%);
    width: 42px;
    height: 42px;
    border-radius: 50%;
    border: 1px solid var(--fm-border);
    background: rgba(255, 255, 255, 0.96);
    color: #475569;
    cursor: pointer;
    z-index: 2;
    box-shadow: var(--fm-shadow);
    transition: all 0.15s;
}

.fm-preview-nav:hover {
    background: var(--fm-primary);
    color: #fff;
    border-color: var(--fm-primary);
}

.fm-preview-nav.fm-prev {
    left: 16px;
}

.fm-preview-nav.fm-next {
    right: 16px;
}

.fm-preview-footer {
    display: flex;
    justify-content: flex-end;
    gap: 10px;
    padding: 14px 24px;
    border-top: 1px solid var(--fm-border);
}

/* Tokens */
.fm-selected-tokens {
    display: flex;
    flex-wrap: wrap;
    gap: 6px;
    margin: 8px 0;
}

.fm-token {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    padding: 4px 10px;
    background: var(--fm-primary-50);
    color: var(--fm-primary-600);
    border: 1px solid var(--fm-primary-100);
    border-radius: 9999px;
    font-size: 12px;
    font-weight: 600;
    animation: fm-pop-in 0.15s var(--fm-ease);
}

.fm-token i {
    cursor: pointer;
    font-size: 12px;
    opacity: 0.7;
    transition: opacity 0.15s;
}

.fm-token i:hover {
    opacity: 1;
}

/* =========================================================
   RESPONSIVE
========================================================= */
@media (max-width: 1100px) {
    .fm-stats {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }
}

@media (max-width: 900px) {
    .fm-sidebar {
        width: 200px;
        min-width: 200px;
    }

    .fm-main {
        padding: 20px;
    }
}

@media (max-width: 680px) {
    .fm-app {
        display: block;
    }

    .fm-sidebar {
        width: 100%;
        min-width: 0;
        min-height: auto;
        border-right: none;
        border-bottom: 1px solid var(--fm-border);
    }

    .fm-sidebar-bottom-art {
        display: none;
    }

    .fm-menu {
        display: flex;
        flex-wrap: wrap;
        gap: 6px;
        padding: 12px;
    }

    .fm-menu-label {
        display: none;
    }

    .fm-menu a {
        flex: 1 1 45%;
        margin: 0;
    }

    .fm-menu a.active::before {
        display: none;
    }

    .fm-main {
        padding: 16px;
    }

    .fm-stats {
        grid-template-columns: 1fr;
    }

    .fm-hero-banner {
        flex-direction: column;
        text-align: center;
        gap: 16px;
    }

    .fm-hero-graphic {
        justify-content: center;
    }

    .fm-search-pill,
    .fm-search-pill:focus-within {
        width: 100%;
    }

    .fm-header-actions {
        width: 100%;
    }
}

/* Respect reduced-motion preference */
@media (prefers-reduced-motion: reduce) {

    .fm-app *,
    .fm-app *::before,
    .fm-app *::after {
        animation-duration: 0.01ms !important;
        transition-duration: 0.01ms !important;
    }
}
a.fm-privacy-btn { text-decoration: none; }
.fm-sidebar .fm-privacy-btn:not(.active) { cursor: pointer; }
/* ADD THESE LINES AT THE END OF THE CSS OF BOTH WIDGETS (keep your existing CSS) */

a.fm-privacy-btn { text-decoration: none; }

/* file name + nickname badge */
.fm-file-name-wrap {
    display: flex;
    flex-direction: column;
    gap: 3px;
    min-width: 0;
}

.fm-nick {
    display: inline-flex;
    align-items: center;
    gap: 5px;
    width: fit-content;
    max-width: 260px;
    padding: 1px 9px;
    border-radius: 9999px;
    background: var(--fm-primary-50);
    color: var(--fm-primary-600);
    border: 1px solid var(--fm-primary-100);
    font-size: 11px;
    font-weight: 600;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.fm-nick i { font-size: 10px; }

sp_widget.script:
(function () {
    /*
     * File Manager Widget (PRIVATE) - Server Script
     * Public files/folders are handled by the separate "public_files" widget
     * and are never loaded or created here.
     *
     * Tables used:
     *   x_1830514_fm_file    - File records
     *   x_1830514_fm_folder  - Folder records
     *   x_1830514_fm_share   - Share records
     */

    var FILE_TABLE   = 'x_1830514_fm_file';
    var FOLDER_TABLE = 'x_1830514_fm_folder';
    var SHARE_TABLE  = 'x_1830514_fm_share';

    var userId = gs.getUserID();
    var _myGroupIds = null;   // cache

    /* ---- Initialise response ---- */
    data.files          = [];
    data.folders        = [];
    data.sharedFiles    = [];
    data.sharedFolders  = [];
    data.sharedByMe     = [];
    data.recycleFiles   = [];
    data.recycleFolders = [];
    data.users          = [];
    data.groups         = [];
    data.storage        = { fileCount: 0, totalBytes: 0, byType: [] };
    data.g_ck           = gs.getSession().getSessionToken();
    data.error          = '';
    data.success        = '';
    data.loaded         = false;   // client only replaces its data when this is true

    var uName = gs.getUserDisplayName() || gs.getUserName() || 'SK';
    data.user_name = uName;
    var nameParts = uName.trim().split(/\s+/);
    data.user_initials = nameParts.length > 1
        ? (nameParts[0].charAt(0) + nameParts[nameParts.length - 1].charAt(0)).toUpperCase()
        : (uName.length >= 2 ? uName.substring(0, 2).toUpperCase() : 'SK');

    try {
        if (input && input.action === 'search_users')     { searchUsers();    return; }
        if (input && input.action === 'search_groups')    { searchGroups();   return; }
        if (input && input.action === 'attach_to_record') { attachToRecord(); return; }

        if (input && input.action) {
            processAction();
            /* do not reload after a failed action, or when the client asks to skip (batch uploads) */
            if (data.error || input.skip_load) return;
        }

        loadData();

    } catch (e) {
        gs.error('FileManagerWidget error: ' + e.message + '\n' + e.stack);
        data.error = 'An unexpected server error occurred. Please refresh and try again.';
    }

    /* ==================================================
       ACTION DISPATCHER
    ================================================== */

    function processAction() {
        switch (input.action) {
            case 'refresh': break;
            case 'create_folder':             createFolder();           break;
            case 'rename_folder':             renameFolder();           break;
            case 'create_file':               createFile();             break;
            case 'discard_file':              discardFile();            break;
            case 'update_file':               updateFile();             break;
            case 'rename_file':               renameFile();             break;
            case 'delete_file':               deleteFile();             break;
            case 'delete_folder':             deleteFolder();           break;
            case 'restore_file':              restoreFile();            break;
            case 'restore_folder':            restoreFolder();          break;
            case 'delete_file_permanent':     deleteFilePermanent();    break;
            case 'delete_folder_permanent':   deleteFolderPermanent();  break;
            case 'share':                     shareItem();              break;
            case 'revoke_share':              revokeShare();            break;
            case 'empty_bin':                 emptyBin();               break;
            case 'add_shared_file_to_folder': addSharedFileToFolder();  break;
            default:
                data.error = 'Invalid action: ' + (input.action || '');
        }
    }

    /* ==================================================
       HELPERS & PERMISSIONS
    ================================================== */

    function getRecord(table, sysId) {
        if (!sysId) return null;
        try {
            var gr = new GlideRecord(table);
            if (gr.get(sysId)) return gr;
        } catch (e) { /* ignore */ }
        return null;
    }

    function isDeleted(gr) {
        var v = String(gr.getValue('is_deleted'));
        return v === '1' || v === 'true';
    }

    /** Set a field only when the table actually has it (avoids errors on optional columns) */
    function _setIf(gr, field, value) {
        if (gr.isValidField(field)) gr.setValue(field, value);
    }

    /* ---- Nickname helpers (uses the "nickname" column if it exists, otherwise a [nick:...] marker in description) ---- */
    function cleanNick(s) { return String(s || '').replace(/[\[\]]/g, '').trim().substring(0, 50); }
    function cleanDescText(d) {
        return String(d || '').replace(/\[nick:[^\]]*\]\s*/ig, '').replace(/\[public\]\s*/ig, '').trim();
    }
    function readNick(gr) {
        if (gr.isValidField('nickname')) return gr.getValue('nickname') || '';
        var m = (gr.getValue('description') || '').match(/\[nick:([^\]]*)\]/i);
        return m ? m[1] : '';
    }
    function writeNick(gr, nick) {
        nick = cleanNick(nick);
        if (gr.isValidField('nickname')) { gr.setValue('nickname', nick); return; }
        var d = (gr.getValue('description') || '').replace(/\[nick:[^\]]*\]\s*/ig, '').trim();
        gr.setValue('description', (d ? d + ' ' : '') + (nick ? '[nick:' + nick + ']' : ''));
    }

    /** Public records belong to the Public Files widget */
    function isRecordPublic(gr) {
        if (!gr) return false;
        if (gr.isValidField('is_public')) {
            var v = gr.getValue('is_public');
            if (v === true || v === 'true' || v === '1' || v === 1) return true;
        }
        if (gr.isValidField('access')) {
            var a = (gr.getValue('access') || '').toLowerCase();
            if (a === 'public') return true;
        }
        var desc = gr.getValue('description') || '';
        return desc.indexOf('[public]') !== -1;
    }

    /** sys_ids of all groups the current user belongs to (cached) */
    function getMyGroupIds() {
        if (_myGroupIds) return _myGroupIds;
        var ids = [];
        var gm = new GlideRecord('sys_user_grmember');
        gm.addQuery('user', userId);
        gm.query();
        while (gm.next()) ids.push(String(gm.getValue('group')));
        _myGroupIds = ids;
        return ids;
    }

    function isActiveShare(share) {
        var activeVal = String(share.getValue('active'));
        if (activeVal !== '1' && activeVal !== 'true') return false;

        var expiry = share.getValue('expiration_date');
        if (expiry) {
            var expiryDate = new GlideDateTime(expiry);
            var now = new GlideDateTime();
            if (expiryDate.getNumericValue() < now.getNumericValue()) return false;
        }
        return true;
    }

    /** Share applies to the user only via direct user / group membership */
    function isShareForUser(share) {
        if (!isActiveShare(share)) return false;

        var users = (share.getValue('shared_with_user') || '').split(',');
        if (users.indexOf(userId) > -1) return true;

        var groups = (share.getValue('shared_with_group') || '').split(',');
        var mine = getMyGroupIds();
        for (var i = 0; i < groups.length; i++) {
            if (groups[i] && mine.indexOf(groups[i]) > -1) return true;
        }
        return false;
    }

    /** Best share permission ('Viewer'|'Editor'|'') for the current user on one file/folder */
    function getDirectShare(tableField, itemId) {
        var share = new GlideRecord(SHARE_TABLE);
        share.addQuery(tableField, itemId);
        share.addQuery('active', true);

        var qc = share.addQuery('shared_with_user', 'CONTAINS', userId);
        var mine = getMyGroupIds();
        for (var i = 0; i < mine.length; i++) {
            qc.addOrCondition('shared_with_group', 'CONTAINS', mine[i]);
        }
        share.query();

        var best = '';
        while (share.next()) {
            if (isShareForUser(share)) {
                var perm = share.getValue('permission') || 'Viewer';
                if (perm === 'Editor') return 'Editor';
                best = perm;
            }
        }
        return best;
    }

    /** Folder permission is inherited from parent folders (so subfolders of a shared folder work) */
    function getFolderPermission(folderId, depth) {
        depth = depth || 0;
        if (!folderId || depth > 20) return '';

        var folder = getRecord(FOLDER_TABLE, folderId);
        if (!folder || isDeleted(folder)) return '';
        if (folder.getValue('owner') === userId) return 'Owner';

        var direct = getDirectShare('folder', folderId);
        if (direct) return direct;

        var parentId = folder.getValue('parent_folder');
        if (parentId) {
            var inherited = getFolderPermission(parentId, depth + 1);
            return inherited === 'Owner' ? 'Editor' : inherited;
        }
        return '';
    }

    function getFilePermission(file) {
        if (!file || isDeleted(file)) return '';
        if (file.getValue('owner') === userId) return 'Owner';

        var direct = getDirectShare('file', file.getUniqueValue());
        if (direct) return direct;

        var folderId = file.getValue('folder');
        if (folderId) {
            var fp = getFolderPermission(folderId);
            return fp === 'Owner' ? 'Editor' : fp;
        }
        return '';
    }

    function canEdit(permission)  { return permission === 'Owner' || permission === 'Editor'; }
    function canOwnFile(file)     { return !!file && file.getValue('owner') === userId; }
    function canOwnFolder(folder) { return !!folder && folder.getValue('owner') === userId; }

    /** Latest attachment id of one file record */
    function getAttachmentId(fileId) {
        var att = new GlideRecord('sys_attachment');
        att.addQuery('table_name', FILE_TABLE);
        att.addQuery('table_sys_id', fileId);
        att.orderByDesc('sys_created_on');
        att.setLimit(1);
        att.query();
        if (att.next()) return att.getUniqueValue();
        return '';
    }

    /**
     * PERFORMANCE: one query for all attachments instead of one query per file.
     * Takes several file lists, fills attachment_id on every item.
     */
    function fillAttachmentIds(lists) {
        var ids = [], seen = {}, map = {}, i, j;
        for (i = 0; i < lists.length; i++) {
            for (j = 0; j < lists[i].length; j++) {
                var id = lists[i][j].sys_id;
                if (!seen[id]) { seen[id] = true; ids.push(id); }
            }
        }
        if (ids.length) {
            var att = new GlideRecord('sys_attachment');
            att.addQuery('table_name', FILE_TABLE);
            att.addQuery('table_sys_id', 'IN', ids.join(','));
            att.orderBy('sys_created_on');            // oldest first -> newest overwrites
            att.query();
            while (att.next()) map[att.getValue('table_sys_id')] = att.getUniqueValue();
        }
        for (i = 0; i < lists.length; i++) {
            for (j = 0; j < lists[i].length; j++) lists[i][j].attachment_id = map[lists[i][j].sys_id] || '';
        }
    }

    /** Push a private file into a list. Returns the pushed object (or null if no permission / public) */
    function addFileToList(file, target, isShareRoot) {
        if (isRecordPublic(file)) return null;       // public files live in the Public Files widget

        var permission = getFilePermission(file);
        if (!permission) return null;

        var fn = file.getValue('filename') || file.getValue('file_name') ||
                 file.getValue('name') || file.getDisplayValue() || '';

        var obj = {
            sys_id:         file.getUniqueValue(),
            filename:       fn,
            folder:         file.getValue('folder') || '',
            folder_name:    file.getDisplayValue('folder') || '',
            description:    cleanDescText(file.getValue('description')),
            nickname:       readNick(file),
            owner:          file.getValue('owner') || '',
            file_extension: file.getValue('file_extension') || '',
            file_size:      parseInt(file.getValue('file_size'), 10) || 0,
            content_type:   file.getValue('content_type') || '',
            attachment_id:  '',                       // filled in one batch by fillAttachmentIds()
            permission:     permission,
            can_edit:       canEdit(permission),
            share_root:     !!isShareRoot,
            sys_created_on: file.getValue('sys_created_on') || '',
            created_date:   file.getDisplayValue('sys_created_on') || ''
        };
        target.push(obj);
        return obj;
    }

    function addFolderToList(folder, target, isShareRoot) {
        if (isRecordPublic(folder)) return null;

        var permission = getFolderPermission(folder.getUniqueValue());
        if (!permission) return null;

        var fn = folder.getValue('folder_name') || folder.getValue('name') || folder.getDisplayValue() || '';

        var color = '';
        if (folder.isValidField('color')) color = folder.getValue('color') || '';
        if (!color && folder.isValidField('folder_color')) color = folder.getValue('folder_color') || '';
        var rawDesc = folder.getValue('description') || '';
        if (!color) {
            var m = rawDesc.match(/\[color:([a-z0-9#-]+)\]/i);
            if (m) color = m[1];
        }
        color = color || 'orange';
        var cleanDesc = rawDesc.replace(/\[color:[a-z0-9#-]+\]\s*/ig, '').trim();

        var obj = {
            sys_id:         folder.getUniqueValue(),
            folder_name:    fn,
            parent_folder:  folder.getValue('parent_folder') || '',
            description:    cleanDesc,
            color:          color,
            owner:          folder.getValue('owner') || '',
            sys_created_on: folder.getValue('sys_created_on') || '',
            created_date:   folder.getDisplayValue('sys_created_on') || '',
            permission:     permission,
            can_edit:       canEdit(permission),
            share_root:     !!isShareRoot
        };
        target.push(obj);
        return obj;
    }

    function _deleteShares(field, itemId) {
        var sh = new GlideRecord(SHARE_TABLE);
        sh.addQuery(field, itemId);
        sh.query();
        sh.deleteMultiple();
    }

    function _deleteAttachments(fileId) {
        var att = new GlideRecord('sys_attachment');
        att.addQuery('table_name', FILE_TABLE);
        att.addQuery('table_sys_id', fileId);
        att.query();
        att.deleteMultiple();
    }

    /* Helper: check if one of MY private folders exists by name and parent */
    function _findFolderId(folderName, parentFolder, excludeId) {
        if (!folderName) return '';
        var gr = new GlideRecord(FOLDER_TABLE);
        gr.addQuery('owner', userId);
        gr.addQuery('is_deleted', false);

        var nameCond = gr.addQuery('folder_name', folderName);
        nameCond.addOrCondition('name', folderName);

        if (parentFolder) {
            gr.addQuery('parent_folder', parentFolder);
        } else {
            gr.addNullQuery('parent_folder');
        }

        if (excludeId) {
            gr.addQuery('sys_id', '!=', excludeId);
        }

        gr.query();
        while (gr.next()) {
            if (!isRecordPublic(gr)) return gr.getUniqueValue();
        }
        return '';
    }

    /* Helper: merge two comma-separated lists of IDs into unique list */
    function _mergeLists(existingList, newList) {
        var map = {};
        var out = [];
        var list1 = String(existingList || '').split(',');
        var list2 = String(newList || '').split(',');

        function add(items) {
            for (var i = 0; i < items.length; i++) {
                var item = String(items[i] || '').trim();
                if (item && !map[item]) {
                    map[item] = true;
                    out.push(item);
                }
            }
        }
        add(list1);
        add(list2);
        return out.join(',');
    }

    /* ==================================================
       ATTACH FILE(S) TO A TARGET RECORD (picker mode)
    ================================================== */

    function attachToRecord() {
        data.attached_count = 0;

        var ids         = input.file_ids || [];
        var targetTable = (input.target_table || '').trim();
        var targetId    = (input.target_sys_id || '').trim();

        if (!ids.length || !targetTable || !targetId) {
            data.error = 'Missing file or target record details.';
            return;
        }

        var secure = new GlideRecordSecure(targetTable);
        if (!secure.isValid()) { data.error = 'Invalid target table.'; return; }
        if (!secure.get(targetId)) { data.error = 'Target record not found. Save the record first.'; return; }
        if (!secure.canWrite()) { data.error = 'You do not have permission to attach files to this record.'; return; }

        var target = new GlideRecord(targetTable);
        target.get(targetId);

        var gsa    = new GlideSysAttachment();
        var failed = [];

        for (var i = 0; i < ids.length; i++) {
            var file = getRecord(FILE_TABLE, ids[i]);

            if (!file || isDeleted(file) || !getFilePermission(file)) {
                failed.push('a file you cannot access');
                continue;
            }

            var attId = getAttachmentId(file.getUniqueValue());
            if (!attId) { failed.push(file.getValue('filename') || 'a file'); continue; }

            var att = new GlideRecord('sys_attachment');
            if (!att.get(attId)) { failed.push(file.getValue('filename') || 'a file'); continue; }

            var newId = gsa.writeContentStream(
                target, att.getValue('file_name'), att.getValue('content_type'), gsa.getContentStream(attId)
            );

            if (newId) data.attached_count++;
            else failed.push(att.getValue('file_name'));
        }

        if (failed.length) data.error = 'Could not attach: ' + failed.join(', ');
        else data.success = data.attached_count + ' file(s) attached.';
    }

    /* ==================================================
       SEARCH USERS & GROUPS
    ================================================== */

    function searchUsers() {
        data.users = [];
        var term = (input.search_term || '').trim();
        if (term.length < 2) return;

        var users = new GlideRecord('sys_user');
        users.addQuery('active', true);
        users.addQuery('sys_id', '!=', userId);

        var cond = users.addQuery('name', 'CONTAINS', term);
        cond.addOrCondition('user_name', 'CONTAINS', term);
        cond.addOrCondition('email', 'CONTAINS', term);

        users.orderBy('name');
        users.setLimit(50);
        users.query();

        while (users.next()) {
            data.users.push({
                sys_id:    users.getUniqueValue(),
                name:      users.getValue('name') || '',
                user_name: users.getValue('user_name') || '',
                email:     users.getValue('email') || ''
            });
        }
    }

    function searchGroups() {
        data.groups = [];
        var term = (input.search_term || '').trim();
        if (term.length < 2) return;

        var groups = new GlideRecord('sys_user_group');
        groups.addQuery('active', true);
        groups.addQuery('name', 'CONTAINS', term);
        groups.orderBy('name');
        groups.setLimit(50);
        groups.query();

        while (groups.next()) {
            data.groups.push({
                sys_id:      groups.getUniqueValue(),
                name:        groups.getValue('name') || '',
                description: groups.getValue('description') || ''
            });
        }
    }

    /* ==================================================
       FOLDERS
    ================================================== */

    function createFolder() {
        var folderName   = (input.folder_name || '').trim();
        var parentFolder = (input.parent_folder || '').trim();
        var description  = (input.description || '').trim();

        if (!folderName) { data.error = 'Please enter a folder name.'; return; }
        if (folderName.length > 40) { data.error = 'Folder name cannot exceed 40 characters.'; return; }

        if (parentFolder) {
            var parent = getRecord(FOLDER_TABLE, parentFolder);
            if (!parent || isDeleted(parent)) { data.error = 'Parent folder not found.'; return; }
            if (isRecordPublic(parent)) {
                data.error = 'Public folders are managed on the Public Files page.';
                return;
            }
            if (!canEdit(getFolderPermission(parent.getUniqueValue()))) {
                data.error = 'You do not have permission to create a subfolder here.';
                return;
            }
        }

        var existingId = _findFolderId(folderName, parentFolder, null);
        if (existingId) {
            /* Folder upload re-uses an existing folder with the same name */
            if (input.reuse_existing) {
                data.folder_sys_id = existingId;
                data.success = 'Using existing folder "' + folderName + '".';
                return;
            }
            data.error = 'A folder with this name already exists in this location.';
            return;
        }

        var folder = new GlideRecord(FOLDER_TABLE);
        folder.initialize();
        if (folder.isValidField('folder_name')) folder.setValue('folder_name', folderName);
        else if (folder.isValidField('name'))   folder.setValue('name', folderName);
        else                                     folder.setValue('folder_name', folderName);

        var color = (input.color || 'orange').trim().toLowerCase();
        _setIf(folder, 'color', color);
        _setIf(folder, 'folder_color', color);

        var storedDesc = description;
        if (!folder.isValidField('color') && !folder.isValidField('folder_color')) {
            storedDesc = (description ? description + ' ' : '') + '[color:' + color + ']';
        }

        folder.setValue('owner', userId);
        folder.setValue('description', storedDesc);
        folder.setValue('is_deleted', false);
        _setIf(folder, 'active', true);
        if (parentFolder) folder.setValue('parent_folder', parentFolder);

        var folderId = folder.insert();
        if (!folderId) {
            data.error = 'Unable to create folder. Please check your permissions.';
            return;
        }

        data.success = 'Folder "' + folderName + '" created successfully.';
        data.folder_sys_id = folderId;
    }

    function renameFolder() {
        var newName  = (input.folder_name || '').trim();
        var targetId = (input.sys_id || '').trim();

        if (!newName || !targetId) { data.error = 'Folder ID and new name are required.'; return; }
        if (newName.length > 40)   { data.error = 'Folder name cannot exceed 40 characters.'; return; }

        var folder = getRecord(FOLDER_TABLE, targetId);
        if (!folder || isDeleted(folder)) { data.error = 'Folder not found.'; return; }
        if (!canOwnFolder(folder))        { data.error = 'Only the folder owner can rename this folder.'; return; }

        var parentFolder = folder.getValue('parent_folder') || '';
        if (_findFolderId(newName, parentFolder, targetId)) {
            data.error = 'A folder with this name already exists in this location.';
            return;
        }

        folder.setValue('folder_name', newName);

        var color = (input.color || '').trim().toLowerCase();
        if (color) {
            _setIf(folder, 'color', color);
            _setIf(folder, 'folder_color', color);
            if (!folder.isValidField('color') && !folder.isValidField('folder_color')) {
                var currentDesc = folder.getValue('description') || '';
                currentDesc = currentDesc.replace(/\[color:[a-z0-9#-]+\]\s*/ig, '').trim();
                folder.setValue('description', (currentDesc ? currentDesc + ' ' : '') + '[color:' + color + ']');
            }
        }

        if (!folder.update()) { data.error = 'Unable to rename folder.'; return; }

        data.success = 'Folder renamed to "' + newName + '".';
    }

    function deleteFolder() {
        var folder = getRecord(FOLDER_TABLE, input.sys_id);
        if (!folder || isDeleted(folder) || !canOwnFolder(folder)) {
            data.error = 'Only the folder owner can delete this folder.';
            return;
        }

        var childFolders = new GlideRecord(FOLDER_TABLE);
        childFolders.addQuery('parent_folder', folder.getUniqueValue());
        childFolders.addQuery('is_deleted', false);
        childFolders.setLimit(1);
        childFolders.query();
        if (childFolders.hasNext()) { data.error = 'Please delete or move all subfolders first.'; return; }

        var files = new GlideRecord(FILE_TABLE);
        files.addQuery('folder', folder.getUniqueValue());
        files.addQuery('is_deleted', false);
        files.setLimit(1);
        files.query();
        if (files.hasNext()) { data.error = 'Please delete or move all files in this folder first.'; return; }

        folder.setValue('is_deleted', true);
        _setIf(folder, 'deleted_by', userId);
        _setIf(folder, 'deleted_date', new GlideDateTime());
        _setIf(folder, 'active', false);
        folder.update();

        data.success = 'Folder moved to Recycle Bin.';
    }

    function restoreFolder() {
        var folder = getRecord(FOLDER_TABLE, input.sys_id);
        if (!folder || !canOwnFolder(folder) || !isDeleted(folder)) {
            data.error = 'You cannot restore this folder.';
            return;
        }

        var parentId = folder.getValue('parent_folder');
        if (parentId) {
            var parent = getRecord(FOLDER_TABLE, parentId);
            if (!parent || isDeleted(parent)) { data.error = 'Please restore the parent folder first.'; return; }
        }

        if (_findFolderId(folder.getValue('folder_name'), parentId || '', folder.getUniqueValue())) {
            data.error = 'A folder with this name already exists in that location.';
            return;
        }

        folder.setValue('is_deleted', false);
        _setIf(folder, 'deleted_by', '');
        _setIf(folder, 'deleted_date', '');
        _setIf(folder, 'active', true);
        folder.update();

        data.success = 'Folder restored successfully.';
    }

    function deleteFolderPermanent() {
        var folder = getRecord(FOLDER_TABLE, input.sys_id);
        if (!folder || !canOwnFolder(folder) || !isDeleted(folder)) {
            data.error = 'You cannot permanently delete this folder.';
            return;
        }

        var folderId = folder.getUniqueValue();

        var childFolders = new GlideRecord(FOLDER_TABLE);
        childFolders.addQuery('parent_folder', folderId);
        childFolders.setLimit(1);
        childFolders.query();
        if (childFolders.hasNext()) {
            data.error = 'Cannot delete this folder because subfolders still exist (check the Recycle Bin and delete them first).';
            return;
        }

        var files = new GlideRecord(FILE_TABLE);
        files.addQuery('folder', folderId);
        files.setLimit(1);
        files.query();
        if (files.hasNext()) {
            data.error = 'Cannot delete this folder because files still exist (check the Recycle Bin and delete them first).';
            return;
        }

        _deleteShares('folder', folderId);
        folder.deleteRecord();
        data.success = 'Folder permanently deleted.';
    }

    /* ==================================================
       FILES
    ================================================== */

    function createFile() {
        var filename = (input.filename || '').trim();
        var folderId = (input.folder || '').trim();

        if (!filename || !folderId) { data.error = 'File name and destination folder are required.'; return; }
        if (filename.length > 255)  { data.error = 'File name is too long (max 255 characters).'; return; }

        var folder = getRecord(FOLDER_TABLE, folderId);
        if (!folder || isDeleted(folder)) { data.error = 'Destination folder not found.'; return; }
        if (isRecordPublic(folder)) {
            data.error = 'Public folders are managed on the Public Files page.';
            return;
        }

        if (!canEdit(getFolderPermission(folder.getUniqueValue()))) {
            data.error = 'You do not have permission to upload into this folder.';
            return;
        }

        var file = new GlideRecord(FILE_TABLE);
        file.initialize();
        if (file.isValidField('filename'))        file.setValue('filename', filename);
        else if (file.isValidField('file_name'))  file.setValue('file_name', filename);
        else if (file.isValidField('name'))       file.setValue('name', filename);
        else                                      file.setValue('filename', filename);

        file.setValue('folder', folderId);
        file.setValue('owner', userId);
        file.setValue('file_extension', (input.extension || '').toLowerCase());
        file.setValue('file_size', parseInt(input.file_size, 10) || 0);
        file.setValue('content_type', input.content_type || 'application/octet-stream');
        file.setValue('is_deleted', false);
        _setIf(file, 'current_version', 1);
        writeNick(file, input.nickname);

        var fileId = file.insert();
        if (!fileId) { data.error = 'Unable to create file record. Please check your permissions.'; return; }

        data.file_sys_id = fileId;
        data.success = 'File record created.';
    }

    /** Remove a file record whose attachment upload failed (prevents empty orphan records) */
    function discardFile() {
        var file = getRecord(FILE_TABLE, input.sys_id);
        if (!file || !canOwnFile(file)) return;
        if (getAttachmentId(file.getUniqueValue())) return;   // has an attachment - keep it
        file.deleteRecord();
    }

    function updateFile() {
        var file = getRecord(FILE_TABLE, input.sys_id);
        if (!file || isDeleted(file)) { data.error = 'File not found.'; return; }
        if (isRecordPublic(file)) { data.error = 'Public files are managed on the Public Files page.'; return; }
        if (!canEdit(getFilePermission(file))) { data.error = 'You do not have permission to edit this file.'; return; }

        var keepNick = readNick(file);
        file.setValue('description', cleanDescText(input.description).substring(0, 900));
        writeNick(file, input.nickname !== undefined ? input.nickname : keepNick);
        if (!file.update()) { data.error = 'Unable to update file.'; return; }

        data.success = 'File updated successfully.';
    }

    /** rename a file (owner only). Keeps the extension field and the attachment name in sync. */
    function renameFile() {
        var newName = (input.filename || '').trim();
        var file = getRecord(FILE_TABLE, input.sys_id);

        if (!newName) { data.error = 'Please enter a file name.'; return; }
        if (newName.length > 255) { data.error = 'File name is too long (max 255 characters).'; return; }
        if (/[\\\/]/.test(newName)) { data.error = 'File name cannot contain slashes.'; return; }
        if (!file || isDeleted(file)) { data.error = 'File not found.'; return; }
        if (!canOwnFile(file)) { data.error = 'Only the file owner can rename this file.'; return; }

        if (file.isValidField('filename'))       file.setValue('filename', newName);
        else if (file.isValidField('file_name')) file.setValue('file_name', newName);
        else if (file.isValidField('name'))      file.setValue('name', newName);

        var ext = newName.indexOf('.') !== -1 ? newName.split('.').pop().toLowerCase() : '';
        _setIf(file, 'file_extension', ext);

        if (!file.update()) { data.error = 'Unable to rename file.'; return; }

        try {   // keep the downloaded file name consistent
            var attId = getAttachmentId(file.getUniqueValue());
            if (attId) {
                var att = new GlideRecord('sys_attachment');
                if (att.get(attId)) { att.setValue('file_name', newName); att.update(); }
            }
        } catch (e) { gs.warn('FileManager rename: attachment name not updated: ' + e.message); }

        data.success = 'File renamed to "' + newName + '".';
    }

    function deleteFile() {
        var file = getRecord(FILE_TABLE, input.sys_id);
        if (!file || isDeleted(file) || !canOwnFile(file)) {
            data.error = 'Only the file owner can delete this file.';
            return;
        }

        _setIf(file, 'original_folder', file.getValue('folder'));
        file.setValue('is_deleted', true);
        _setIf(file, 'deleted_by', userId);
        _setIf(file, 'deleted_date', new GlideDateTime());
        file.update();

        data.success = 'File moved to Recycle Bin.';
    }

    function restoreFile() {
        var file = getRecord(FILE_TABLE, input.sys_id);
        if (!file || !canOwnFile(file) || !isDeleted(file)) {
            data.error = 'You cannot restore this file.';
            return;
        }

        var originalFolder = file.isValidField('original_folder') ? file.getValue('original_folder') : '';
        if (originalFolder) {
            var folder = getRecord(FOLDER_TABLE, originalFolder);
            if (!folder || isDeleted(folder)) {
                data.error = 'The original folder no longer exists. Please restore it first.';
                return;
            }
            file.setValue('folder', originalFolder);
        }

        file.setValue('is_deleted', false);
        _setIf(file, 'deleted_by', '');
        _setIf(file, 'deleted_date', '');
        _setIf(file, 'original_folder', '');
        file.update();

        data.success = 'File restored successfully.';
    }

    function deleteFilePermanent() {
        var file = getRecord(FILE_TABLE, input.sys_id);
        if (!file || !canOwnFile(file) || !isDeleted(file)) {
            data.error = 'You cannot permanently delete this file.';
            return;
        }

        var fileId = file.getUniqueValue();
        _deleteAttachments(fileId);
        _deleteShares('file', fileId);
        file.deleteRecord();
        data.success = 'File permanently deleted.';
    }

    function emptyBin() {
        var files = new GlideRecord(FILE_TABLE);
        files.addQuery('owner', userId);
        files.addQuery('is_deleted', true);
        files.query();
        while (files.next()) {
            if (isRecordPublic(files)) continue;     // belongs to the Public Files recycle bin
            var fid = files.getUniqueValue();
            _deleteAttachments(fid);
            _deleteShares('file', fid);
            files.deleteRecord();
        }

        var folders = new GlideRecord(FOLDER_TABLE);
        folders.addQuery('owner', userId);
        folders.addQuery('is_deleted', true);
        folders.query();
        while (folders.next()) {
            if (isRecordPublic(folders)) continue;
            _deleteShares('folder', folders.getUniqueValue());
            folders.deleteRecord();
        }

        data.success = 'Recycle Bin emptied.';
    }

    /* ==================================================
       ADD SHARED FILE OR FOLDER TO MY FOLDER
       Creates an independent copy. The original is unchanged.
    ================================================== */

    function addSharedFileToFolder() {
        var sourceId       = String(input.sys_id || '').trim();
        var targetFolderId = String(input.folder_id || '').trim();
        var itemType       = String(input.item_type || input.type || '').toLowerCase();

        if (!sourceId || !targetFolderId) { data.error = 'Source item and destination folder are required.'; return; }

        var targetFolder = getRecord(FOLDER_TABLE, targetFolderId);
        if (!targetFolder || isDeleted(targetFolder)) { data.error = 'Destination folder not found.'; return; }
        if (!canOwnFolder(targetFolder)) { data.error = 'You can only add items to folders owned by you.'; return; }
        if (isRecordPublic(targetFolder)) { data.error = 'Choose one of your private folders.'; return; }

        if (itemType !== 'file' && itemType !== 'folder') {
            var maybeFolder = getRecord(FOLDER_TABLE, sourceId);
            itemType = (maybeFolder && !isDeleted(maybeFolder)) ? 'folder' : 'file';
        }

        if (itemType === 'file') {
            var sourceFile = getRecord(FILE_TABLE, sourceId);
            if (!sourceFile || isDeleted(sourceFile)) { data.error = 'Shared file not found.'; return; }
            if (!getFilePermission(sourceFile)) { data.error = 'You do not have permission to access this file.'; return; }

            var copiedFileId = _copySharedFile(sourceFile, targetFolderId);
            if (!copiedFileId) { data.error = 'Unable to copy the shared file.'; return; }

            data.success = 'Shared file added to your folder successfully.';
            data.new_file_sys_id = copiedFileId;
            return;
        }

        var sourceFolder = getRecord(FOLDER_TABLE, sourceId);
        if (!sourceFolder || isDeleted(sourceFolder)) { data.error = 'Shared folder not found.'; return; }
        if (!getFolderPermission(sourceId)) { data.error = 'You do not have permission to access this folder.'; return; }

        var copiedFolderId = _copySharedFolderTree(sourceFolder, targetFolderId, 0);
        if (!copiedFolderId) {
            if (!data.error) data.error = 'Unable to copy the shared folder.';
            return;
        }

        data.success = 'Shared folder and its contents added successfully.';
        data.new_folder_sys_id = copiedFolderId;
    }

    /** Copy one file record and its attachment */
    function _copySharedFile(sourceFile, targetFolderId) {
        if (!sourceFile || isDeleted(sourceFile)) return '';
        if (!getFilePermission(sourceFile)) return '';

        var newFile = new GlideRecord(FILE_TABLE);
        newFile.initialize();

        var filename = sourceFile.getValue('filename') || sourceFile.getValue('file_name') || sourceFile.getValue('name') || '';

        if (newFile.isValidField('filename'))       newFile.setValue('filename', filename);
        else if (newFile.isValidField('file_name')) newFile.setValue('file_name', filename);
        else if (newFile.isValidField('name'))      newFile.setValue('name', filename);

        newFile.setValue('folder', targetFolderId);
        newFile.setValue('owner', userId);
        _setIf(newFile, 'description',     cleanDescText(sourceFile.getValue('description')));
        _setIf(newFile, 'file_extension',  sourceFile.getValue('file_extension') || '');
        _setIf(newFile, 'file_size',       sourceFile.getValue('file_size') || 0);
        _setIf(newFile, 'content_type',    sourceFile.getValue('content_type') || '');
        _setIf(newFile, 'current_version', 1);
        _setIf(newFile, 'is_deleted',      false);
        writeNick(newFile, readNick(sourceFile));

        var newFileId = newFile.insert();
        if (!newFileId) return '';

        if (getAttachmentId(sourceFile.getUniqueValue())) {
            try {
                new GlideSysAttachment().copy(FILE_TABLE, sourceFile.getUniqueValue(), FILE_TABLE, newFileId);
            } catch (attachmentError) {
                gs.error('File Manager: Attachment copy failed: ' + attachmentError.message);
                var incomplete = getRecord(FILE_TABLE, newFileId);
                if (incomplete) incomplete.deleteRecord();
                return '';
            }
        }
        return String(newFileId);
    }

    /** Copy a shared folder recursively (subfolders + files) */
    function _copySharedFolderTree(sourceFolder, destinationParentId, depth) {
        depth = depth || 0;

        if (depth > 20) { data.error = 'Maximum folder nesting depth exceeded.'; return ''; }
        if (!sourceFolder || isDeleted(sourceFolder)) return '';

        if (!getFolderPermission(sourceFolder.getUniqueValue())) {
            data.error = 'You do not have access to a folder in this structure.';
            return '';
        }

        var destinationParent = getRecord(FOLDER_TABLE, destinationParentId);
        if (!destinationParent || isDeleted(destinationParent) || !canOwnFolder(destinationParent)) {
            data.error = 'Invalid destination folder.';
            return '';
        }

        var folderName = sourceFolder.getValue('folder_name') || sourceFolder.getValue('name') || 'Shared Folder';

        // Avoid duplicate folder names in the destination (folder names are limited to 40 chars)
        var uniqueName = folderName.substring(0, 40), suffix = 1;
        while (_findFolderId(uniqueName, destinationParentId, null)) {
            var tail = ' (Copy ' + suffix + ')';
            uniqueName = folderName.substring(0, 40 - tail.length) + tail;
            if (++suffix > 100) { data.error = 'Unable to generate a unique folder name.'; return ''; }
        }

        var newFolder = new GlideRecord(FOLDER_TABLE);
        newFolder.initialize();
        if (newFolder.isValidField('folder_name')) newFolder.setValue('folder_name', uniqueName);
        else if (newFolder.isValidField('name'))   newFolder.setValue('name', uniqueName);

        newFolder.setValue('owner', userId);
        newFolder.setValue('parent_folder', destinationParentId);
        _setIf(newFolder, 'description', (sourceFolder.getValue('description') || '').replace(/\[public\]\s*/ig, '').trim());
        _setIf(newFolder, 'is_deleted', false);
        _setIf(newFolder, 'active', true);

        var newFolderId = newFolder.insert();
        if (!newFolderId) { data.error = 'Unable to create copied folder: ' + uniqueName; return ''; }

        // files inside
        var files = new GlideRecord(FILE_TABLE);
        files.addQuery('folder', sourceFolder.getUniqueValue());
        files.addQuery('is_deleted', false);
        files.query();
        while (files.next()) {
            if (!_copySharedFile(files, String(newFolderId))) {
                gs.error('File Manager: Could not copy file ' + files.getUniqueValue());
            }
        }

        // child folders (collect ids first so the recursion does not disturb the cursor)
        var subIds = [];
        var subfolders = new GlideRecord(FOLDER_TABLE);
        subfolders.addQuery('parent_folder', sourceFolder.getUniqueValue());
        subfolders.addQuery('is_deleted', false);
        subfolders.query();
        while (subfolders.next()) subIds.push(subfolders.getUniqueValue());

        for (var i = 0; i < subIds.length; i++) {
            var sub = getRecord(FOLDER_TABLE, subIds[i]);
            if (sub) _copySharedFolderTree(sub, String(newFolderId), depth + 1);
        }

        return String(newFolderId);
    }

    /* ==================================================
       SHARE / REVOKE
    ================================================== */

    /** Keep only active records of `table` whose sys_id is in the csv (and drop the owner) */
    function _validIds(table, csv, excludeId) {
        var ids = String(csv || '').split(',').filter(function (x) { return x && x !== excludeId; });
        if (!ids.length) return '';
        var gr = new GlideRecord(table);
        gr.addQuery('sys_id', 'IN', ids.join(','));
        gr.addQuery('active', true);
        gr.query();
        var ok = [];
        while (gr.next()) ok.push(gr.getUniqueValue());
        return ok.join(',');
    }

    function shareItem() {
        var type           = (input.type || '');
        var itemId         = (input.sys_id || '');
        var shareRecipient = (input.recipient_type || 'user');
        var targetUsers    = (input.user_ids || '');
        var targetGroups   = (input.group_ids || '');
        var permission     = 'Viewer';   // fixed least-privilege default; not user-selectable
        var expirationDate = (input.expiration_date || '');

        if (!itemId) { data.error = 'No item specified to share.'; return; }

        var targetField;
        if (type === 'file') {
            var item = getRecord(FILE_TABLE, itemId);
            if (!item || isDeleted(item) || !canOwnFile(item)) { data.error = 'Only the file owner can share this file.'; return; }
            if (isRecordPublic(item)) { data.error = 'Public files are already visible to everyone.'; return; }
            targetField = 'file';
        } else if (type === 'folder') {
            var item2 = getRecord(FOLDER_TABLE, itemId);
            if (!item2 || isDeleted(item2) || !canOwnFolder(item2)) { data.error = 'Only the folder owner can share this folder.'; return; }
            if (isRecordPublic(item2)) { data.error = 'Public folders are already visible to everyone.'; return; }
            targetField = 'folder';
        } else {
            data.error = 'Invalid item type.';
            return;
        }

        if (shareRecipient === 'group') {
            targetGroups = _validIds('sys_user_group', targetGroups, '');
            if (!targetGroups) { data.error = 'Please select at least one valid group.'; return; }
        } else {
            targetUsers = _validIds('sys_user', targetUsers, userId);   // you cannot share with yourself
            if (!targetUsers) { data.error = 'Please select at least one valid user (other than yourself).'; return; }
        }

        var formattedExpiry = '';
        if (expirationDate) {
            formattedExpiry = String(expirationDate).replace('T', ' ').replace(/\.\d+Z?$/, '').replace(/Z$/, '');
            if (formattedExpiry.length === 16) formattedExpiry += ':00';
        }

        var existing = new GlideRecord(SHARE_TABLE);
        existing.addQuery(targetField, itemId);
        existing.addQuery('permission', permission);
        existing.addQuery('shared_by', userId);
        if (formattedExpiry) existing.addQuery('expiration_date', formattedExpiry);
        else existing.addNullQuery('expiration_date');
        existing.query();

        if (existing.next()) {
            existing.setValue('active', true);
            existing.setValue('shared_by', userId);

            if (shareRecipient === 'group') {
                existing.setValue('shared_with_group', _mergeLists(existing.getValue('shared_with_group'), targetGroups));
            } else {
                existing.setValue('shared_with_user', _mergeLists(existing.getValue('shared_with_user'), targetUsers));
            }
            existing.update();
        } else {
            var share = new GlideRecord(SHARE_TABLE);
            share.initialize();
            share.setValue(targetField, itemId);

            if (shareRecipient === 'group') {
                share.setValue('shared_with_group', targetGroups);
                share.setValue('shared_with_user', '');
            } else {
                share.setValue('shared_with_user', targetUsers);
                share.setValue('shared_with_group', '');
            }
            share.setValue('shared_by', userId);
            share.setValue('permission', permission);
            share.setValue('active', true);
            if (formattedExpiry) share.setValue('expiration_date', formattedExpiry);

            if (!share.insert()) { data.error = 'Unable to share this item. Please try again.'; return; }
        }

        data.success = 'Item shared successfully.';
    }

    /** stop sharing (only the person who created the share can revoke it) */
    function revokeShare() {
        var share = getRecord(SHARE_TABLE, input.sys_id);
        if (!share || share.getValue('shared_by') !== userId) {
            data.error = 'You can only revoke shares that you created.';
            return;
        }
        share.setValue('active', false);
        if (!share.update()) { data.error = 'Unable to revoke this share.'; return; }
        data.success = 'Access revoked.';
    }

    /* ==================================================
       LOAD WIDGET DATA
    ================================================== */

    function loadData() {
        loadOwnedFolders();
        loadOwnedFiles();
        loadSharedItems();
        loadSharedByMe();
        loadRecycleBin();
        loadStorage();
        fillAttachmentIds([data.files, data.sharedFiles]);   // ONE query for all attachments
        data.loaded = true;
    }

    function loadOwnedFolders() {
        var folders = new GlideRecord(FOLDER_TABLE);
        folders.addQuery('owner', userId);
        folders.addQuery('is_deleted', false);
        folders.orderBy('folder_name');
        folders.query();
        while (folders.next()) {
            addFolderToList(folders, data.folders, false);   // skips public folders
        }
    }

    function loadOwnedFiles() {
        var files = new GlideRecord(FILE_TABLE);
        files.addQuery('owner', userId);
        files.addQuery('is_deleted', false);
        files.orderByDesc('sys_created_on');
        files.query();
        while (files.next()) {
            addFileToList(files, data.files, false);         // skips public files
        }
    }

    /**
     * "Shared with Me": only items shared WITH the user (user or group), never items the
     * user owns. Shared folders are loaded recursively (subfolders + files).
     */
    function loadSharedItems() {
        var shares = new GlideRecord(SHARE_TABLE);
        shares.addQuery('active', true);

        var qc = shares.addQuery('shared_with_user', 'CONTAINS', userId);
        var mine = getMyGroupIds();
        for (var g = 0; g < mine.length; g++) qc.addOrCondition('shared_with_group', 'CONTAINS', mine[g]);
        shares.query();

        var seenFiles = {}, seenFolders = {};

        while (shares.next()) {
            if (!isShareForUser(shares)) continue;

            var fileId   = shares.getValue('file');
            var folderId = shares.getValue('folder');
            var sharedOn = shares.getDisplayValue('sys_created_on') || '';

            if (fileId) {
                if (seenFiles[fileId]) {
                    seenFiles[fileId].share_root = true;
                } else {
                    var file = getRecord(FILE_TABLE, fileId);
                    if (file && !isDeleted(file) && !canOwnFile(file)) {
                        var fo = addFileToList(file, data.sharedFiles, true);
                        if (fo) { fo.shared_date = sharedOn; seenFiles[fileId] = fo; }
                    }
                }
            }

            if (folderId) {
                var shFolder = getRecord(FOLDER_TABLE, folderId);
                if (shFolder && !isDeleted(shFolder) && !canOwnFolder(shFolder)) {
                    _addSharedFolderTree(folderId, true, seenFolders, seenFiles, 0);
                    if (seenFolders[folderId]) seenFolders[folderId].shared_date = sharedOn;
                }
            }
        }
    }

    /** Items shared by the current user (recipient, dates, status - and the share id for revoking) */
    function loadSharedByMe() {
        var shares = new GlideRecord(SHARE_TABLE);
        shares.addQuery('shared_by', userId);
        shares.orderByDesc('sys_created_on');
        shares.query();

        var nameCache = {};
        function lookupName(table, id, isGroup) {
            var key = table + ':' + id;
            if (nameCache[key] === undefined) {
                var r = getRecord(table, id);
                nameCache[key] = r ? (r.getValue('name') || r.getValue('user_name') || id) : id;
            }
            return nameCache[key] + (isGroup ? ' (Group)' : '');
        }

        while (shares.next()) {
            var fileId   = shares.getValue('file');
            var folderId = shares.getValue('folder');
            var item     = fileId ? getRecord(FILE_TABLE, fileId) : getRecord(FOLDER_TABLE, folderId);
            if (!item || isDeleted(item)) continue;

            var recipients = [];
            var userIds  = (shares.getValue('shared_with_user') || '').split(',');
            var groupIds = (shares.getValue('shared_with_group') || '').split(',');
            for (var i = 0; i < userIds.length; i++)  if (userIds[i])  recipients.push(lookupName('sys_user', userIds[i], false));
            for (var j = 0; j < groupIds.length; j++) if (groupIds[j]) recipients.push(lookupName('sys_user_group', groupIds[j], true));

            data.sharedByMe.push({
                sys_id:            shares.getUniqueValue(),
                item_sys_id:       fileId || folderId || '',
                item_name:         fileId ? (item.getValue('filename') || item.getDisplayValue()) : (item.getValue('folder_name') || item.getDisplayValue()),
                item_type:         fileId ? 'File' : 'Folder',
                item_created_date: item.getDisplayValue('sys_created_on') || '',
                shared_with:       recipients.join(', '),
                shared_date:       shares.getDisplayValue('sys_created_on') || '',
                expiration_date:   shares.getDisplayValue('expiration_date') || '',
                active:            isActiveShare(shares)
            });
        }
    }

    function _addSharedFolderTree(folderId, isRoot, seenFolders, seenFiles, depth) {
        if (depth > 20) return;

        if (seenFolders[folderId]) {
            if (isRoot) seenFolders[folderId].share_root = true;
            return;
        }

        var folder = getRecord(FOLDER_TABLE, folderId);
        if (!folder || isDeleted(folder)) return;

        var obj = addFolderToList(folder, data.sharedFolders, isRoot);
        if (!obj) return;
        seenFolders[folderId] = obj;

        /* files inside */
        var ff = new GlideRecord(FILE_TABLE);
        ff.addQuery('folder', folderId);
        ff.addQuery('is_deleted', false);
        ff.query();
        while (ff.next()) {
            var fid = ff.getUniqueValue();
            if (seenFiles[fid]) continue;
            var fo = addFileToList(ff, data.sharedFiles, false);
            if (fo) seenFiles[fid] = fo;
        }

        /* subfolders */
        var sub = new GlideRecord(FOLDER_TABLE);
        sub.addQuery('parent_folder', folderId);
        sub.addQuery('is_deleted', false);
        sub.query();
        var subIds = [];
        while (sub.next()) subIds.push(sub.getUniqueValue());
        for (var i = 0; i < subIds.length; i++) {
            _addSharedFolderTree(subIds[i], false, seenFolders, seenFiles, depth + 1);
        }
    }

    /* ---- Recycle Bin (private items only) ---- */
    function loadRecycleBin() {
        var folders = new GlideRecord(FOLDER_TABLE);
        folders.addQuery('owner', userId);
        folders.addQuery('is_deleted', true);
        folders.orderByDesc('sys_updated_on');
        folders.query();
        while (folders.next()) {
            if (isRecordPublic(folders)) continue;
            data.recycleFolders.push({
                sys_id:       folders.getUniqueValue(),
                folder_name:  folders.getValue('folder_name') || folders.getValue('name') || folders.getDisplayValue() || '',
                created_date: folders.getDisplayValue('sys_created_on') || '',
                deleted_date: folders.getDisplayValue('deleted_date') || folders.getDisplayValue('sys_updated_on') || ''
            });
        }

        var files = new GlideRecord(FILE_TABLE);
        files.addQuery('owner', userId);
        files.addQuery('is_deleted', true);
        files.orderByDesc('sys_updated_on');
        files.query();
        while (files.next()) {
            if (isRecordPublic(files)) continue;
            var fn = files.getValue('filename') || files.getValue('file_name') || files.getValue('name') || files.getDisplayValue() || '';
            data.recycleFiles.push({
                sys_id:         files.getUniqueValue(),
                filename:       fn,
                file_size:      parseInt(files.getValue('file_size'), 10) || 0,
                file_extension: files.getValue('file_extension') || '',
                content_type:   files.getValue('content_type') || '',
                created_date:   files.getDisplayValue('sys_created_on') || '',
                deleted_date:   files.getDisplayValue('deleted_date') || files.getDisplayValue('sys_updated_on') || ''
            });
        }
    }

    /* ---- Storage Analytics (private files only) ---- */
    function loadStorage() {
        var fileCount = 0;
        var totalBytes = 0;
        var byTypeMap = {};

        var files = new GlideRecord(FILE_TABLE);
        files.addQuery('owner', userId);
        files.addQuery('is_deleted', false);
        files.query();

        while (files.next()) {
            if (isRecordPublic(files)) continue;
            var size = parseInt(files.getValue('file_size'), 10) || 0;
            var ext = (files.getValue('file_extension') || 'unknown').toLowerCase();
            if (!ext) ext = 'unknown';

            fileCount++;
            totalBytes += size;

            if (!byTypeMap[ext]) {
                byTypeMap[ext] = { ext: ext, count: 0, totalBytes: 0 };
            }
            byTypeMap[ext].count++;
            byTypeMap[ext].totalBytes += size;
        }

        var byTypeList = [];
        for (var k in byTypeMap) {
            if (byTypeMap.hasOwnProperty(k)) {
                byTypeList.push(byTypeMap[k]);
            }
        }

        data.storage = {
            fileCount:  fileCount,
            totalBytes: totalBytes,
            byType:     byTypeList
        };
    }

})();
